PUBLIC_TEST_VERDICT_FACT_ENV = "STATEFRAME_PUBLIC_TEST_VERDICT_FACT"


def public_test_verdict_fact_mode(value: object = None) -> str:
    """Return the fail-open, default-off public-verdict fact mode."""
    try:
        raw = (os.environ.get(PUBLIC_TEST_VERDICT_FACT_ENV, "off")
               if value is None else value)
        mode = str(raw or "off").strip().lower()
        return mode if mode in {"off", "shadow", "on"} else "off"
    except Exception:
        return "off"


def _emit_public_test_verdict_fact_event(
        runtime: object, kind: str, **fields: object,
) -> None:
    try:
        emit = getattr(getattr(runtime, "journal", None), "emit", None)
        if callable(emit):
            emit(kind, producer="kernel_stateframe_runtime", dispatch=False, **fields)
    except Exception:
        # Verdict telemetry must never affect the authoritative result.
        pass


def _framefit5_error_detail(
        error: BaseException,
        framefit5_error_type: type[BaseException],
) -> str | None:
    from kernel_frame_request_allocation import FrameRequestAllocationError
    from kernel_stateframe_action_ledger import ActionLedgerError
    if not isinstance(error, (framefit5_error_type, FrameRequestAllocationError, ActionLedgerError)):
        return None
    from kernel_v46_mechanism_wiring import _sanitize_error_text

    try:
        message = str(error)
    except Exception:
        message = "<message unavailable>"
    return _sanitize_error_text(message, 160)


def _prepared_framefit5_state(runtime: object) -> Mapping[str, object] | None:
    context = getattr(runtime, "_framefit_action_context", None)
    framefit5 = context.get("framefit5") if isinstance(context, Mapping) else None
    return framefit5 if isinstance(framefit5, Mapping) else None


def _framefit5_envelope_shape(messages: Sequence[Mapping[str, object]]) -> str:
    """Describe StateFrame shape without retaining payload values in diagnostics."""
    prefix = "[StateFrame]\n"
    states: list[str] = []
    for message in messages:
        content = message.get("content")
        if not isinstance(content, str) or not content.startswith(prefix):
            continue
        boundary = content.find("\n[", len(prefix))
        body = content[len(prefix):] if boundary < 0 else content[len(prefix):boundary]
        try:
            payload = json.loads(body)
        except (TypeError, ValueError, RecursionError):
            states.append("malformed")
            continue
        state = payload.get("state") if isinstance(payload, Mapping) else None
        if not isinstance(state, Mapping):
            states.append("missing_state")
            continue
        framefit5 = state.get("framefit5")
        if not isinstance(framefit5, Mapping):
            states.append("missing_product")
        elif framefit5.get("mode") != "FRAME_ONLY":
            states.append("wrong_mode")
        else:
            states.append("frame_only_product")
    if not states:
        return "no_stateframe"
    return states[0] if len(states) == 1 else "multiple_stateframes"


def _record_framefit5_envelope_shape(
        trace: list[dict[str, str]] | None,
        stage: str,
        messages: Sequence[Mapping[str, object]],
) -> None:
    if trace is not None:
        trace.append({"stage": stage, "shape": _framefit5_envelope_shape(messages)})


DEFERRED_FINALIZATION_NO_CHANGES_ENV = "STATEFRAME_DEFERRED_FINALIZATION_NO_CHANGES"


def deferred_finalization_no_changes_mode(value: object = None) -> str:
    raw = (os.environ.get(DEFERRED_FINALIZATION_NO_CHANGES_ENV, "off")
           if value is None else value)
    result = str(raw or "off").strip().lower()
    if result not in {"off", "on"}:
        raise ValueError(f"{DEFERRED_FINALIZATION_NO_CHANGES_ENV} must be off or on")
    return result


def classify_deferred_finalization_no_changes(runtime: object) -> bool:
    if deferred_finalization_no_changes_mode() != "on":
        return False
    try:
        from kernel_preedit_coverage_runtime import _zero_edits
        if not _zero_edits(runtime):
            return False
    except Exception:  # noqa: BLE001 - uncertain host mutation evidence does not classify
        return False
    runtime.system_outcome = "NO_CHANGES"
    if not getattr(runtime, "_deferred_finalization_no_changes_classified", False):
        runtime._deferred_finalization_no_changes_classified = True
        emit = getattr(getattr(runtime, "journal", None), "emit", None)
        if callable(emit):
            try:
                emit("deferred_finalization_classified",
                     producer="kernel_stateframe_runtime", dispatch=False,
                     reason="finalization_deferred", outcome="NO_CHANGES",
                     applied_product_mutations=0)
            except Exception as error:  # noqa: BLE001 - journal failure cannot change the outcome
                runtime._deferred_finalization_no_changes_event_error = type(error).__name__
    return True


def _invoke_host_phase(
        function, runtime, args, kwargs, *, name, boundary, spans, sequence):
    nested_notice_prepare = (
        name == "prepare"
        and bool(getattr(runtime, "_notice_dedup_in_request", False))
        and os.environ.get("STATEFRAME_TURN_TIMING", "off").strip().lower()
        in {"on", "1", "true", "yes"}
    )
    if nested_notice_prepare:
        return function(runtime, *args, **kwargs)
    measure = getattr(spans, "measure", None)
    if not callable(measure):
        return function(runtime, *args, **kwargs)
    profile_scope = getattr(spans, "request_preparation_scope", None)
    if (name != "prepare" or not kwargs.get("provider_request", True)
            or not callable(profile_scope)):
        with measure(name, boundary=boundary, sequence=sequence):
            return function(runtime, *args, **kwargs)

    profile_step = getattr(getattr(runtime, "owner", None), "current_step", sequence)
    with profile_scope(profile_step) as (profile, created):
        try:
            with measure(name, boundary=boundary, sequence=sequence):
                result = function(runtime, *args, **kwargs)
        except BaseException:
            if created and profile is not None:
                spans.discard_request_profile(profile.request_id)
            raise
    if created and profile is not None:
        result_capture = getattr(result, "capture", None)
        if getattr(result_capture, "request_id", None) != profile.request_id:
            spans.discard_request_profile(profile.request_id)
    return result


def _emit_prepare_timing(journal, runtime, started, *, enabled):
    if not enabled:
        return
    emit = getattr(journal, "emit", None)
    if not callable(emit):
        return
    try:
        active = getattr(runtime, "_active_capture", None)
        emit(
            "request_prepare_timing",
            producer="kernel_stateframe_runtime",
            request_id=getattr(active, "request_id", None),
            step=getattr(runtime, "current_step", None),
            host_seconds=time.perf_counter() - started,
            dispatch=False,
        )
    except (OSError, RuntimeError, TypeError, ValueError):
        pass


def _reprepare_on_source_change(function):
    """Retry one unsent preparation when its source authority changes mid-build."""
    @functools.wraps(function)
    def wrapped(self, messages, *, uncapped, tools, provider_request=True,
                request_host_text_preparer=None, **route_options):
        # route_options carries forced_route/frozen_route_capture for a routed second leg only;
        # unrouted callers never pass it, so their calls are unchanged.
        from kernel_frame_optional_allocation import FrameAllocationReplanNeeded

        if (not provider_request
                or getattr(self, "stateframe_framefit_mode", "off") != "on"
                or getattr(self, "_notice_dedup_in_request", False)
                or getattr(self, "_source_replan_in_progress", False)):
            return function(
                self, messages, uncapped=uncapped, tools=tools,
                provider_request=provider_request,
                request_host_text_preparer=request_host_text_preparer,
                **route_options,
            )
        # The first attempt may mutate its input lists. Preserve caller-owned
        # material before it runs so a retry cannot inherit a stale projection.
        fresh_messages = copy.deepcopy(messages)
        fresh_uncapped = (fresh_messages if messages is uncapped
                          else copy.deepcopy(uncapped))
        fresh_tools = copy.deepcopy(tools)
        try:
            return function(
                self, messages, uncapped=uncapped, tools=tools,
                provider_request=provider_request,
                request_host_text_preparer=request_host_text_preparer,
                **route_options,
            )
        except FrameAllocationReplanNeeded:
            pass
        from kernel_request_reprepare import (
            SourceRevisionReplanRefused, source_replan_preparation,
        )
        try:
            with source_replan_preparation(self, getattr(self, "_active_capture", None)):
                prepared = function(
                    self, fresh_messages, uncapped=fresh_uncapped,
                    tools=fresh_tools, provider_request=provider_request,
                    request_host_text_preparer=request_host_text_preparer,
                    **route_options,
                )
            capture = getattr(prepared, "capture", None)
            if capture is not None:
                capture._source_replan_attempted = True
            return prepared
        except FrameAllocationReplanNeeded as repeated:
            raise SourceRevisionReplanRefused(
                "source_revision_replan_exhausted") from repeated
        except Exception as failure:
            raise SourceRevisionReplanRefused(
                "source_revision_replan_failed") from failure

    return wrapped


def _host_phase(name: str, *, boundary: str = "recorded_prefix"):
    """Measure a complete host seam without changing request/prompt data."""
    def decorate(function):
        @functools.wraps(function)
        def wrapped(self, *args, **kwargs):
            journal = getattr(self, "journal", None)
            spans = getattr(journal, "host_spans", None)
            capture = getattr(self, "_active_capture", None)
            sequence = getattr(capture, "step", None)
            started = time.perf_counter()
            nested_notice_prepare = (
                name == "prepare"
                and bool(getattr(self, "_notice_dedup_in_request", False))
                and os.environ.get("STATEFRAME_TURN_TIMING", "off").strip().lower()
                in {"on", "1", "true", "yes"}
            )
            if nested_notice_prepare:
                return function(self, *args, **kwargs)
            try:
                with turn_timing_step(name):
                    return _invoke_host_phase(
                        function, self, args, kwargs, name=name, boundary=boundary,
                        spans=spans, sequence=sequence,
                    )
            finally:
                _emit_prepare_timing(
                    journal, self, started,
                    enabled=(name == "prepare" and kwargs.get("provider_request", True)
                             and not nested_notice_prepare),
                )
        return wrapped
    return decorate


def _clear_dispatch_facts(function):
    """Clear request facts after a completed or settled action, never on menu no-ops."""
    @functools.wraps(function)
    def wrapped(self, *args, **kwargs):
        ledger = getattr(self, "step_ledger", None)
        try:
            pending = getattr(ledger, "pending", None) if ledger is not None else None
        except Exception:
            pending = None
        try:
            return function(self, *args, **kwargs)
        finally:
            if pending is not None:
                from kernel_host_cache import (
                    clear_request_cache, optimized_turn_facts_enabled,
                    request_cache_invalidation_changed,
                )
                if (not optimized_turn_facts_enabled()
                        or request_cache_invalidation_changed(self)):
                    clear_request_cache(self)
    return wrapped


def _install_py39_dataclass_compat() -> None:
    """Keep optional StateFrame dataclasses importable on the v46 Python 3.9 runner."""
    if sys.version_info >= (3, 10) or getattr(dataclasses.dataclass, "_stateframe_py39", False):
        return
    original = dataclasses.dataclass

    def compatible_dataclass(cls=None, /, **kwargs):
        kwargs.pop("slots", None)
        kwargs.pop("weakref_slot", None)
        if cls is None:
            return lambda target: original(target, **kwargs)
        return original(cls, **kwargs)

    compatible_dataclass._stateframe_py39 = True
    dataclasses.dataclass = compatible_dataclass


_install_py39_dataclass_compat()
install_telemetry_patch()


