def gate_evidence_identity(value: object) -> object:
    """Stable, JSON-serializable identity for pass-gate evidence.

    Dataclasses (e.g. ``ShipTreeSmokeResult``) become their field mapping, mappings and
    sequences recurse, JSON primitives pass through, anything else becomes ``repr`` so the
    gate vector digest never raises on a host-owned object (10-06 batch 836: a TypeError here
    made ``done`` uncertifiable while every public check was green)."""
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        return gate_evidence_identity(dataclasses.asdict(value))
    if isinstance(value, Mapping):
        return {str(key): gate_evidence_identity(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set, frozenset)):
        items = [gate_evidence_identity(item) for item in value]
        return sorted(items, key=repr) if isinstance(value, (set, frozenset)) else items
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    return repr(value)


def host_closure_task_id(owner) -> str:
    """Full task id for check-bundle lookup.

    owner.task_id is the legacy 8-char sha prefix (d["sha"][:8] -> "crawl-l-", "long-dev"), which never
    matches a bundle; the task row carries the real id. Found 09-25: host closure had zero checks live.
    """
    row = getattr(owner, "task_row", {})
    if isinstance(row, Mapping):
        full = row.get("task_id")
        if isinstance(full, str) and full:
            return full
    return str(getattr(owner, "task_id", "") or "")


def attach_idealpath(runtime: object, *, resume: object | None = None):
    """Attach the IDEALPATH reducer to one live runtime instance.

    Default on; ``STATEFRAME_IDEALPATH=off`` attaches nothing (returns None) so
    every ``_idealpath_owner()`` consumer takes its owner-is-None native path.
    """
    from kernel_idealpath import SCHEMA, attach, enabled as idealpath_enabled
    if not idealpath_enabled(runtime):
        runtime.journal.emit(
            "idealpath_disabled", producer="kernel_idealpath",
            mode_env="STATEFRAME_IDEALPATH", dispatch=False,
        )
        return None
    from kernel_s1_force import build_s1_host_draft

    owner = getattr(runtime, "owner", None)
    row = getattr(owner, "task_row", {})
    row = row if isinstance(row, Mapping) else {}
    binding = runtime.binding()
    base_revision = str(binding.get("product_revision") or binding.get("artifact") or "")
    from kernel_request_evidence_closure import ticket_identity_from_row
    ticket = ticket_identity_from_row(row)
    ticket_hash = ticket.sha256 if ticket is not None else "sha256:" + hashlib.sha256(b"").hexdigest()
    task_id = str(row.get("task_id", ""))
    # Transport/completion launch fixtures intentionally have no IDEALPATH
    # ticket; their public checks exercise the legacy completion rail only.
    if task_id.startswith(("launch-smoke-", "paths2-", "paths2-launch-smoke-")):
        span_source = ()
    else:
        span_source = row.get("idealpath_ticket_spans", row.get("public_check_paths", ()))
    spans = tuple(
        str(item) for item in span_source
        if isinstance(item, str) and item
    )
    ticket_text = ticket.text if ticket is not None else ""
    host_draft = None
    if span_source and ticket_text and not task_id.startswith(
            ("launch-smoke-", "paths2-", "paths2-launch-smoke-")):
        try:
            from kernel_row_role import NEW_BEHAVIOR, draft_role
            _row_role = draft_role(runtime)   # Q3: cached facts only; REPAIR keeps the old draft
            host_draft = build_s1_host_draft(
                task_id or "ticket", ticket_text,
                row_role=_row_role if _row_role.get("role") == NEW_BEHAVIOR else None)
            spans = tuple(str(item["id"]) for item in host_draft["spans"])
        except Exception as error:  # noqa: BLE001 - draft failure remains observable and fail-closed
            runtime.journal.emit(
                "idealpath_host_draft_error",
                producer="kernel_s1_force",
                error_type=type(error).__name__,
                dispatch=False,
            )
    snapshot = None
    records = getattr(getattr(runtime, "journal", None), "records", None)
    if resume is not None and callable(records):
        for event in records():
            if isinstance(event, Mapping) and event.get("kind") == "idealpath_state":
                candidate = event.get("state")
                if isinstance(candidate, Mapping) and candidate.get("schema") == SCHEMA:
                    snapshot = candidate
    idealpath_owner = attach(
        runtime,
        ticket_hash=ticket_hash,
        base_revision=base_revision,
        ticket_spans=spans,
        snapshot=snapshot,
        host_draft=host_draft,
        semantic_reviewer=getattr(runtime, "idealpath_semantic_reviewer", None),
    )
    if (
        not isinstance(getattr(runtime, "requirements_ledger", None), Mapping)
        and isinstance(host_draft, Mapping)
        and isinstance(host_draft.get("requirement_ledger"), Mapping)
    ):
        # The S1 host draft is the public-ticket source for this live owner;
        # bind its admitted ledger before S2/S3 can consume row identities.
        runtime.requirements_ledger = copy.deepcopy(dict(host_draft["requirement_ledger"]))
    if isinstance(getattr(runtime, "requirements_ledger", None), Mapping):
        runtime._idealpath_bind_spine()
    runtime.journal.emit(
        "idealpath_owner_attached",
        producer="kernel_idealpath",
        event_schema=SCHEMA,
        stage=idealpath_owner.stage,
        state_epoch=idealpath_owner.epoch,
        restored=snapshot is not None,
        host_draft_digest=(host_draft or {}).get("draft_digest") if isinstance(host_draft, Mapping) else None,
        host_draft_rows=len(host_draft.get("rows", ())) if isinstance(host_draft, Mapping) else 0,
        dispatch=False,
    )
    try:
        from kernel_adversary import attach as attach_adversary
        attach_adversary(runtime)
    except Exception as error:  # noqa: BLE001 - advisory pressure cannot block runtime attach
        runtime.journal.emit(
            "adversary_error",
            producer="kernel_adversary",
            phase="owner_attach",
            error_type=type(error).__name__,
            dispatch=False,
        )
    return idealpath_owner


