def _insert_before_protected_tail(
        messages: Sequence[Mapping[str, object]],
        message: Mapping[str, object],
        continuation: Mapping[str, object] | None,
) -> list[dict]:
    """Insert an opt-in sidecar before boot-owned state/prefill messages."""
    config = continuation if isinstance(continuation, Mapping) else {}
    protected_tail = int(config.get("state_placement", "off") == "end")
    protected_tail += int(config.get("think_prefill", "off") == "on")
    rendered = [dict(item) for item in messages]
    rendered.insert(max(0, len(rendered) - protected_tail), dict(message))
    return rendered


def _lean_no_host_recovery_tools(runtime: object, tools: object) -> list[dict[str, object]]:
    """Order the no-host recovery surface without losing the current admission.

    The no-host terminal handoff is a frozen compatibility menu: it is emitted
    before a run has a host-backed state frame to recall from, and its exact
    schema is checked by the public release smoke.  The indexed ``recall``
    action remains available on ordinary and host-backed terminal frames.
    """
    current = [copy.deepcopy(dict(tool)) for tool in tools
               if isinstance(tool, Mapping)] if isinstance(tools, Sequence) else []
    full = getattr(runtime, "_completion_owner_full_tools", ())
    if (not isinstance(full, Sequence) or not full
            or isinstance(full, (str, bytes, bytearray))):
        return current
    preferred_names = (
        "done", "run_tests", "edit", "str_replace", "read",
        "grep", "list_files", "file_create", "file_delete", "file_move", "shell", "read_check_receipt",
        "where_defined", "who_calls", "references", "decide",
        "launch_job", "job_status", "job_output", "job_kill",
        "note_update", "note_retrieve", "recall_evidence", "recall",
    )
    by_name = {
        str(tool.get("function", {}).get("name", "")): tool
        for tool in full
        if isinstance(tool, Mapping) and isinstance(tool.get("function"), Mapping)
    }
    ordered = [by_name[name] for name in preferred_names
               if name in by_name and name != "recall"]
    ordered_names = {
        str(tool.get("function", {}).get("name", "")) for tool in ordered
    }
    return [
        *[copy.deepcopy(dict(tool)) for tool in ordered],
        *[copy.deepcopy(dict(tool)) for tool in full
          if isinstance(tool, Mapping)
           and str(tool.get("function", {}).get("name", "")) not in ordered_names
           and str(tool.get("function", {}).get("name", "")) != "recall"],
    ]


def _emit_render_degraded_once(
        journal: object, already_recorded: bool, **fields: object) -> bool:
    """Journal one render-degradation fact per provider request."""
    if already_recorded:
        return True
    journal.emit("render_degraded", **fields)
    return True


def _memory_capsule_wire_enabled() -> bool:
    """Read the switch without importing/validating the opt-in module off-arm."""
    return os.environ.get("STATEFRAME_MEMORY_CAPSULE", "off").strip().lower() in {"1", "on"}


def _without_public_proof_locators(frame: dict) -> dict:
    """Omit audit-only locators before snapshot hashing, without mutating host proof.

    ``supporting_evidence`` remains available on the host-owned Verdict.  In
    the public-proof-omitted projection its event references are deliberately
    blanked because they contain run-scoped IDs; the verdict state and reason
    codes remain semantic and stable for model-facing rendering.
    """
    def public_proof(value: object) -> object:
        if not isinstance(value, dict):
            return value
        return {key: [] if key == "supporting_evidence" else item
                for key, item in value.items() if key != "receipt_id"}

    public = dict(frame)
    if isinstance(frame.get("verification"), dict):
        public["verification"] = public_proof(frame["verification"])
    if isinstance(frame.get("completion_verdict"), dict):
        public["completion_verdict"] = public_proof(frame["completion_verdict"])
    contract = frame.get("completion_contract")
    if isinstance(contract, dict) and isinstance(contract.get("current_public_checks"), dict):
        public["completion_contract"] = {
            **contract,
            "current_public_checks": public_proof(contract["current_public_checks"]),
        }
    world = frame.get("world")
    if isinstance(world, dict):
        public_world = dict(world)
        if isinstance(world.get("last_test"), dict):
            public_world["last_test"] = {
                key: value for key, value in world["last_test"].items() if key != "receipt_id"}
        if isinstance(world.get("certification"), dict):
            public_world["certification"] = public_proof(world["certification"])
        public["world"] = public_world
    return public


@dataclasses.dataclass(frozen=True)
class PreparedRequest:
    messages: tuple[dict, ...]
    capture: RequestCapture
    overflow: dict | None = None
    # Exact final tool contract sent to the provider.  The dispatch loop uses
    # this same contract for pre-dispatch validation; menu projections cannot
    # drift between preparation and execution.
    tools: tuple[dict, ...] | None = None

    @property
    def pending_qualification(self) -> bool:
        return bool(getattr(self.capture, "_framefit5_pending_qualification", False))

    @property
    def frame_request_allocation(self) -> FrameRequestAllocation | None:
        allocation = getattr(self.capture, "frame_request_allocation", None)
        if allocation is not None and not isinstance(allocation, FrameRequestAllocation):
            raise TypeError("prepared request has an invalid frame request allocation")
        return allocation


