def _r44_any_render_switch(runtime: object) -> bool:
    return (any(getattr(runtime, attr, "off") == "on" for attr in _R44_RENDER_MODE_ATTRS)
            or getattr(runtime, "boot_mode", "off") not in ("off", "", None))


def _r44_rendered_blocks(messages: object) -> list[dict]:
    """[{mechanism, header, tokens}] for every r44 block found at the START of a line in the wire messages."""
    found: list[dict] = []
    for message in messages if isinstance(messages, (list, tuple)) else ():
        content = message.get("content") if isinstance(message, Mapping) else None
        if not isinstance(content, str):
            continue
        for prefix, mechanism in R44_BLOCK_PREFIXES:
            at = content.find(prefix)
            if at == -1 or (at > 0 and content[at - 1] != "\n"):
                continue
            nxt = content.find("\n\n[", at + len(prefix))
            block = content[at:] if nxt == -1 else content[at:nxt]
            found.append({"mechanism": mechanism, "header": prefix,
                          "tokens": token_estimate({"messages": [{"role": "user", "content": block}]})})
    return found


def _r44_plugged_keys(runtime: object) -> list[tuple[str, str]]:
    """r44 staging: (manifest key, value) for every r44 switch that is ON and had no PLUGGED key of its own.

    Nothing is returned for an off switch, so every off-arm manifest is byte-identical to r43.  jq_class_edit and
    probe_validity_gate have no runtime attribute (the runner/public review read them), so their module mode is used.
    """
    out: list[tuple[str, str]] = []
    if getattr(runtime, "stateframe_unified_stop_mode", "off") == "on":
        out.append(("stateframe_unified_stop", "on"))
    if getattr(runtime, "stateframe_working_sets_mode", "off") == "on":
        out.append(("stateframe_working_sets", "on"))
    if getattr(runtime, "stateframe_working_notes_mode", "off") == "on":
        out.append(("stateframe_working_notes", "on"))
    if getattr(runtime, "stateframe_delivery_contract_mode", "off") == "on":
        out.append(("stateframe_delivery_contract", "on"))
    if getattr(runtime, "boot_mode", "off") not in ("off", "", None):
        out.append(("stateframe_boot", str(getattr(runtime, "boot_mode"))))
    if getattr(runtime, "stateframe_playbook_selfplan_mode", "off") == "on":
        out.append(("stateframe_playbook_selfplan", "on"))
    if getattr(runtime, "figure_it_out_enabled", False) is True:
        out.append(("stateframe_figure_it_out", "on"))
    from kernel_jq_class_edit import enabled as jq_class_edit_enabled
    if jq_class_edit_enabled():
        out.append(("stateframe_jq_class_edit", "on"))
    from kernel_probe_validity_gate import enabled as probe_validity_enabled
    if probe_validity_enabled():
        out.append(("stateframe_probe_validity_gate", "on"))
    if getattr(runtime, "stateframe_settled_findings_mode", "off") == "on":
        out.append(("stateframe_settled_findings", "on"))
    if getattr(runtime, "stateframe_memory_capsule_mode", "off") == "on":
        out.append(("stateframe_memory_capsule", "on"))
    if getattr(runtime, "stateframe_delivery_audit_mode", "off") == "on":
        out.append(("stateframe_delivery_audit", "on"))
    return out


