def configured_closure_reserve() -> int:
    """Read the opt-in verification+done reserve without changing OFF runs."""
    raw = os.environ.get(CLOSURE_RESERVE_ENV, "0")
    if isinstance(raw, str) and raw.lower() == "on":
        return CLOSURE_RESERVE_DEFAULT
    if isinstance(raw, str) and raw.lower() == "off":
        return 0
    try:
        value = int(raw)
    except (TypeError, ValueError) as error:
        raise ValueError(f"{CLOSURE_RESERVE_ENV} must be a nonnegative integer") from error
    if value < 0:
        raise ValueError(f"{CLOSURE_RESERVE_ENV} must be a nonnegative integer")
    return value


def _clip_render_text(value: object, limit: int) -> str:
    """Bound render-only text without changing the host-owned evidence."""
    text = str(value or "")
    if len(text) <= limit:
        return text
    marker = "\n[... render excerpt omitted ...]\n"
    if limit <= len(marker):
        return marker[:max(1, limit)]
    available = limit - len(marker)
    head = available // 2
    return text[:head] + marker + text[-(available - head):]


def _red_test_excerpt(frame: Mapping[str, object]) -> str | None:
    """Return the latest host-observed RED test feedback, if present."""
    feedback = frame.get("recent_test_feedback")
    if not isinstance(feedback, Sequence) or isinstance(feedback, (str, bytes)):
        return None
    for record in reversed(feedback):
        if not isinstance(record, Mapping) or record.get("result") not in {
                "RED", "FAILED", "fail"}:
            continue
        text = record.get("feedback") or record.get("observation")
        if isinstance(text, str) and text.strip():
            from kernel_wire_identity import public_wire_text
            text = public_wire_text(text, None)  # DETFIX4b: raw RED output -> stable model text
            target = record.get("parameters", {}).get("target", "") \
                if isinstance(record.get("parameters"), Mapping) else ""
            return ("[RED test failure excerpt]"
                    + (f" target={target}" if target else "") + "\n"
                    + _clip_render_text(text, 2600))
    return None


def _current_unresolved_check(frame: Mapping[str, object]
                              ) -> tuple[str | None, Mapping[str, object] | None]:
    """Return only a latest RED result; a later green check closes the old excerpt."""
    feedback = frame.get("recent_test_feedback")
    if not isinstance(feedback, Sequence) or isinstance(feedback, (str, bytes)):
        return None, None
    latest = next((record for record in reversed(feedback)
                   if isinstance(record, Mapping) and record.get("result") is not None), None)
    if not isinstance(latest, Mapping):
        return None, None
    if str(latest.get("result") or "").strip().casefold() not in {"red", "failed", "fail"}:
        return None, None
    normalized = dict(latest)
    normalized["result"] = "RED"
    excerpt = _red_test_excerpt({"recent_test_feedback": [normalized]})
    return excerpt, latest


def _unresolved_check_source_path(record: Mapping[str, object] | None) -> str | None:
    if not isinstance(record, Mapping):
        return None
    params = record.get("parameters")
    if not isinstance(params, Mapping):
        return None
    for key in ("path", "target_path", "target"):
        value = params.get(key)
        if isinstance(value, str) and value.strip():
            candidate = value.strip().split("::", 1)[0]
            return candidate
    return None


def _compact_frame_for_overflow(frame: Mapping[str, object], failure: str | None) -> str:
    """Keep decision-critical state while dropping provenance-heavy frame fields."""
    keys = ("phase", "atomic_completion", "last_action", "recent_change_verification", "completion_contract",
            "budget", "pending", "verification", "host_review", "known_violations",
            "host_observed_findings", "recent_test_feedback", "recent_negative_actions")
    compact = {key: copy.deepcopy(frame[key]) for key in keys if key in frame}
    if isinstance(compact.get("recent_test_feedback"), list):
        compact["recent_test_feedback"] = [
            {key: (_clip_render_text(value, 2600) if key in {"feedback", "observation"}
                   else copy.deepcopy(value))
             for key, value in item.items()}
            for item in compact["recent_test_feedback"][-2:]
            if isinstance(item, Mapping)]
    compact["render_notice"] = _RENDER_OMISSION_NOTICE
    if failure:
        compact["failure_excerpt_pinned"] = True
    return "[StateFrame; render-degraded]\n" + json.dumps(
        compact, sort_keys=True, ensure_ascii=False, default=str)


def _retained_omission(item: SelectableItem) -> str:
    """Render an optional span marker without asking for a doomed workspace reread."""
    return (f"[Retained source excerpt omitted: {item.group}]\n"
            f"Read hint: recall_evidence(reference={item.retrievable_ref!r}) "
            "before relying on this optional source.\n"
            + _RENDER_OMISSION_NOTICE)


def _requested_retained_ids(retained_evidence: Sequence[Mapping[str, object]],
                            items: Sequence[SelectableItem]) -> set[str]:
    """Return the newest explicitly requested retained result."""
    rows = list(retained_evidence)
    explicit = [row for row in rows if row.get("requested_delivery") is True]
    row = explicit[-1] if explicit else None
    if row is None:
        candidates = [item for item in items
                      if item.item_id.startswith("retained:") and item.action_required]
        return {candidates[-1].item_id} if candidates else set()
    span_id = row.get("span_id")
    reference = row.get("reference")
    for item in reversed(items):
        if not item.item_id.startswith("retained:"):
            continue
        if (span_id and (item.item_id == "retained:" + str(span_id) or
                         item.item_id.endswith(str(span_id)))) or (
                reference and item.retrievable_ref == str(reference)):
            return {item.item_id}
    return set()


def _delivery_audit_span_row(row: Mapping[str, object]) -> dict[str, object]:
    """Preserve runtime selection semantics when projecting retained evidence."""
    result = copy.deepcopy(dict(row))
    if result.get("required") is None:
        result["required"] = result.get(
            "action_required", result.get("requested_delivery") is True)
    return result


def _retained_recall_followup_required(evidence: Mapping[str, object],
                                       retained: object,
                                       frame: Mapping[str, object]) -> bool:
    """Keep current source visible in the frame immediately after a recall.

    The shared verdict adds bounded completion facts to the operational frame.
    That can consume the optional evidence margin even though a current source
    is the necessary companion to an explicit historical recall.  Pin only
    that immediate follow-up; ordinary retained-source selection stays optional.
    """
    last_action = frame.get("last_action")
    if (not isinstance(last_action, Mapping)
            or last_action.get("tool") != "recall_evidence"
            or evidence.get("freshness") != "current"):
        return False
    requested = getattr(retained, "requested", "")
    revisions = getattr(getattr(retained, "archive", None), "revisions", {})
    requested_source = revisions.get(requested) if isinstance(revisions, Mapping) else None
    return (bool(requested) and isinstance(requested_source, Mapping)
            and requested_source.get("path") == evidence.get("path"))


def _requested_read_excerpt(item: SelectableItem, row: Mapping[str, object]) -> str:
    """Keep a requested read as a bounded, explicitly line-ranged result."""
    path = str(row.get("path") or "the retained source")
    start = int(row.get("start_line") or 1)
    end = row.get("selected_end_line") or row.get("end_line") or start
    try:
        end = int(end)
    except (TypeError, ValueError):
        end = start
    header = (f"[Requested retained read | path={path!r} | "
              f"lines {start}-{max(start, end)}]\n")
    return header + _clip_render_text(item.text, 1200)


def _render_block_kind(content: object) -> str | None:
    """Classify model-facing blocks for deterministic per-block budgeting."""
    text = str(content or "")
    if text.startswith("[StateFrame v2 S1"):
        return "s1"
    if text.startswith("[StateFrame playbook sidecar]"):
        # Fix round (rv_playbook_selfplan_REPORT.md finding 1): classification
        # was purely content-based, so an ordinary PUBLIC message that merely
        # begins with this exact header text activated clip/drop budgeting
        # even with STATEFRAME_PLAYBOOK_SELFPLAN off -- OFF was not
        # byte-identical.  Gate on the feature mode, through the shared header
        # constant, so an unrelated OFF payload is never reclassified.
        from kernel_playbook_selfplan import PLAYBOOK_HEADER, playbook_mode
        if playbook_mode() == "on" and text.startswith(PLAYBOOK_HEADER):
            return "playbook"
        return None
    if text.startswith("[StateFrame advisory sidecar]") or text.startswith("[BOOT CAPSULE"):
        return "boot"
    if text.startswith(("[Generated artifact catalog",
                        "[Generated artifact; UNVERIFIED proposal]",
                        "[Generated artifact recall",
                        "[Generated artifact statement",
                        "[Generated assistant statement",
                        "[Assistant statement")):
        return "generated"
    if text.startswith("[Rejected candidate;"):
        return "rejected"
    if text.startswith(("[INTERVENTION", "[Intervention", "[RETRY", "[Retry")):
        return "intervention"
    if text.startswith("[WORKING_VIEW"):
        return "working_view"
    if text.startswith("[Repository signals v1"):
        return "repo_signals"
    return None


# Presentation budgets only; the shared render ceiling and model reasoning
# budget remain unchanged.
_OPTIONAL_BLOCK_BUDGETS = {
    "s1": 450,
    "playbook": 320,
    "boot": 320,
    "rejected": 220,
    "intervention": 260,
    "working_view": 420,
    "repo_signals": 560,
}
_OPTIONAL_DROP_ORDER = ("repo_signals", "rejected", "intervention", "s1", "playbook", "boot")


_GENERATED_AUTHORITY_LABELS = (
    "MODEL_GENERATED_UNVERIFIED",
    "NOT_REVALIDATED_FOR_CURRENT_WORKSPACE",
)


def _is_required_generated_block(content: object) -> bool:
    """Return whether a generated projection is required model context.

    GeneratedContext is only attached when its feature is enabled.  Its catalog,
    explicit recall result, and optional assistant-statement card therefore share
    one delivery rule: advisory stack cards may be dropped, but generated
    content may not.  Keep this predicate based on the wire header as well as the
    authority labels so restart-era recall renderings remain pinned even if their
    header differs from the catalog header.
    """
    text = str(content or "")
    return (_render_block_kind(text) == "generated" or
            any(label in text for label in _GENERATED_AUTHORITY_LABELS))


def _has_advisory_blocks(messages: Sequence[Mapping[str, object]]) -> bool:
    # A working view is a normal arm block.  The pre-budget pass is activated
    # only by the stack-specific advisory sidecars, preserving OFF payloads.
    return any(_render_block_kind(message.get("content")) in {
        "s1", "playbook", "boot", "generated", "rejected", "intervention", "repo_signals"}
               for message in messages)


def _bound_optional_blocks(messages: Sequence[dict], tools: object,
                           ceiling_tokens: int) -> tuple[list[dict], bool]:
    """Cap/drop advisory blocks before source, latest exchange, and reads."""
    bounded = [copy.deepcopy(message) for message in messages]
    changed = False
    for message in bounded:
        kind = _render_block_kind(message.get("content"))
        budget = _OPTIONAL_BLOCK_BUDGETS.get(kind)
        if budget is None:
            continue
        content = str(message.get("content") or "")
        clipped = _clip_render_text(content, max(120, budget * 4 - 32))
        if clipped != content:
            message["content"] = clipped
            changed = True

    def estimate(value: Sequence[dict]) -> int:
        return token_estimate({"messages": list(value), "tools": tools})

    if estimate(bounded) <= ceiling_tokens:
        return bounded, changed
    for kind in _OPTIONAL_DROP_ORDER:
        kept = []
        removed = False
        for message in bounded:
            if _render_block_kind(message.get("content")) == kind:
                removed = True
                changed = True
            else:
                kept.append(message)
        bounded = kept
        if removed and estimate(bounded) <= ceiling_tokens:
            break
    return bounded, changed


def _is_pinned_render_message(message: Mapping[str, object], index: int,
                               pinned_references: set[str], *,
                               memory_capsule_enabled: bool = False) -> bool:
    """Identify facts that optional/advisory blocks may never evict."""
    from kernel_decision_continuity import BLOCK_HEADER, enabled as continuity_enabled
    role = message.get("role")
    text = str(message.get("content") or "")
    if index < 2 or role in {"assistant", "tool"}:
        return True
    if _is_required_generated_block(text):
        return True
    if memory_capsule_enabled:
        from kernel_stateframe_memory_capsule import CAPSULE_HEADER_PREFIX
        if text.startswith(CAPSULE_HEADER_PREFIX):
            # A capsule is already independently bounded and must never be clipped
            # into a different typed record.  If the whole request cannot fit, the
            # final ceiling check returns overflow instead.
            return True
    if continuity_enabled() and text.startswith(BLOCK_HEADER):
        return True
    if text.startswith(("[StateFrame]", "[Continuation]", "[Working source:",
                        "[Current source:",
                        "[Requested retained read", "[RED test failure excerpt]",
                        "[WORKING_VIEW", "[WORK RECORD]", "[disposition-v2]",
                        "[Your previous step —")):
        return True
    return bool(pinned_references and any(ref in text for ref in pinned_references))


def _fit_requested_message(message: dict) -> None:
    """Turn a retained source block into a line-ranged excerpt before clipping."""
    text = str(message.get("content") or "")
    if not text.startswith(("[Retained source:", "[Current source:")):
        return
    if text.startswith("[Current source:") and "[Source metadata]\n" not in text:
        # Frame-clarity's compact current-source block has no retained metadata;
        # it is already the working file and must not be relabelled as a read.
        return
    metadata = re.search(r"\[Source metadata\]\n(\{.*?\})", text, re.S)
    row: dict[str, object] = {}
    if metadata:
        try:
            value = json.loads(metadata.group(1))
            if isinstance(value, dict):
                row = value
        except (TypeError, ValueError, json.JSONDecodeError):
            pass
    path = str(row.get("path") or "the retained source")
    start = int(row.get("start_line") or 1)
    end = row.get("selected_end_line") or row.get("end_line") or start
    try:
        end = int(end)
    except (TypeError, ValueError):
        end = start
    message["content"] = (f"[Requested retained read | path={path!r} | "
                           f"lines {start}-{max(start, end)}]\n" +
                           _clip_render_text(text, 1200))


def _degraded_render_plan(items: Sequence[SelectableItem], messages: Mapping[str, dict],
                          *, frame: Mapping[str, object], budget_tokens: int,
                          ceiling_tokens: int, mode: Mode,
                          retained_evidence: Sequence[Mapping[str, object]] = ()) -> tuple[
                              ViewPlan, dict[str, dict]]:
    """Build a deterministic RED-recovery view after atomic selection overflows.

    The retained archive remains complete and retrievable.  Only its model-facing
    presentation is reduced: the current target source and the latest failing test
    excerpt are required, while whole-file retained spans become cheap read hints.
    """
    rendered = copy.deepcopy(dict(messages))
    failure = _red_test_excerpt(frame)
    failure_text = failure or _RENDER_OMISSION_NOTICE
    compact_frame = _compact_frame_for_overflow(frame, failure)
    degraded: list[SelectableItem] = []

    def replace_message(item: SelectableItem, content: str, *, priority=None,
                        action_required: bool | None = None) -> SelectableItem:
        message = copy.deepcopy(rendered.get(item.item_id, {"role": "user", "content": content}))
        message["content"] = content
        rendered[item.item_id] = message
        return dataclasses.replace(
            item, text=canonical_bytes(message).decode(),
            token_estimate=token_estimate(message),
            priority=item.priority if priority is None else priority,
            action_required=(item.action_required if action_required is None else action_required))

    retained_by_id = {
        "retained:" + str(row.get("span_id")): row
        for row in retained_evidence if row.get("span_id")}
    requested_ids = _requested_retained_ids(retained_evidence, items)
    for item in items:
        if item.item_id == "frame:facts":
            degraded.append(replace_message(item, compact_frame))
        elif item.item_id.startswith("retained:"):
            row = retained_by_id.get(item.item_id, {})
            if not row:
                row = next((candidate for candidate in retained_evidence
                            if (candidate.get("span_id") and
                                item.item_id.endswith(str(candidate["span_id"]))) or
                            (candidate.get("reference") and
                             item.retrievable_ref == str(candidate["reference"]))), {})
            if item.item_id in requested_ids:
                content = _requested_read_excerpt(item, row)
                degraded.append(replace_message(
                    item, content, priority=Priority.REQUIRED_CONTROL_CONTEXT,
                    action_required=True))
            else:
                degraded.append(replace_message(
                    item, _retained_omission(item),
                    priority=Priority.DECISION_LINKED_EVIDENCE, action_required=False))
        elif (item.item_id == "generated_artifacts" or
              _is_required_generated_block(
                  rendered.get(item.item_id, {}).get("content", item.text))):
            # Generated catalog/recall/statement content is required whenever the
            # generated feature is enabled.  Preserve it byte-for-byte here:
            # generic render clipping can remove the authority labels that tell
            # the model this is unverified and not revalidated workspace state.
            degraded.append(replace_message(
                item, rendered.get(item.item_id, {}).get("content", item.text),
                priority=Priority.REQUIRED_CONTROL_CONTEXT, action_required=True))
        elif item.item_id in {"public_review", "rejected_candidate"}:
            degraded.append(replace_message(item, _clip_render_text(
                rendered.get(item.item_id, {}).get("content", item.text), 1200),
                priority=Priority.DECISION_LINKED_EVIDENCE, action_required=False))
        elif item.item_id.startswith("observed_source:"):
            degraded.append(replace_message(item, _clip_render_text(
                rendered.get(item.item_id, {}).get("content", item.text), 1200),
                priority=Priority.DECISION_LINKED_EVIDENCE, action_required=False))
        else:
            degraded.append(item)

    failure_id = "failure:latest_test"
    failure_message = {"role": "user", "content": failure_text}
    rendered[failure_id] = failure_message
    degraded.append(SelectableItem(
        failure_id, Priority.REQUIRED_CONTROL_CONTEXT, "failure", failure_text,
        token_estimate(failure_message), dependencies=("frame:facts",), action_required=True))

    selected = select_view(degraded, budget_tokens=budget_tokens,
                           ceiling_tokens=ceiling_tokens, mode=mode)
    if isinstance(selected, ViewPlan):
        return dataclasses.replace(
            selected,
            margin_reasons=tuple(selected.margin_reasons) + (
                "render_degraded_after_required_overflow",)), rendered

    # If the required minimum still cannot fit, send a tiny explicit recovery
    # view.  A requested read is still delivered as a line-ranged excerpt; it
    # must never be replaced by an instruction to issue the same read again.
    omission_id = "render:omission_notice"
    omission = failure_text + "\n" + _RENDER_OMISSION_NOTICE
    degraded_rendered = rendered
    rendered = {omission_id: {"role": "user", "content": omission}}
    notice = SelectableItem(omission_id, Priority.REQUIRED_CONTROL_CONTEXT, omission_id,
                            omission, token_estimate(rendered[omission_id]), action_required=True)
    requested = next((item for item in degraded if item.item_id in requested_ids), None)
    selected_fallback: list[SelectableItem] = []
    if requested is not None:
        content = degraded_rendered.get(requested.item_id, {}).get("content", requested.text)
        # Leave enough room for the line-range header and keep shrinking the
        # excerpt until its own serialized block fits the unchanged ceiling.
        while token_estimate({"role": "user", "content": content}) > ceiling_tokens:
            if len(content) <= 24:
                content = content[:max(1, ceiling_tokens * 4)]
                break
            content = _clip_render_text(content, max(24, (len(content) * 3) // 4))
        requested = dataclasses.replace(
            requested, text=content,
            token_estimate=token_estimate({"role": "user", "content": content}))
        rendered[requested.item_id] = {"role": "user", "content": content}
        selected_fallback.append(requested)
    if not selected_fallback and notice.token_estimate <= ceiling_tokens:
        selected_fallback.append(notice)
    elif (selected_fallback and
          sum(item.token_estimate for item in selected_fallback) + notice.token_estimate
          <= ceiling_tokens):
        selected_fallback.append(notice)
    if not selected_fallback:
        # The configured ceiling is at least one token by construction; keep a
        # bounded explicit marker if even the wrapper cannot fit.
        tiny = {"role": "user", "content": "[Render degraded]"}
        rendered = {omission_id: tiny}
        notice = dataclasses.replace(notice, text=tiny["content"],
                                     token_estimate=token_estimate(tiny))
        selected_fallback = [notice]
    used = sum(item.token_estimate for item in selected_fallback)
    return ViewPlan(tuple(selected_fallback), (), used, budget_tokens,
                    "stateframe-render/1", margin_reasons=(
                        "render_degraded_after_minimum_overflow",)), rendered


def _fit_rendered_messages(messages: Sequence[dict], tools: object,
                            ceiling_tokens: int, *,
                            pinned_references: Sequence[str] = (),
                            memory_capsule_enabled: bool = False) -> tuple[list[dict], bool]:
    """Bound post-selection sidecars too; return whether an omission was made."""
    prepared, optional_changed = _bound_optional_blocks(
        messages, tools, ceiling_tokens)
    capsule_prefix = ""
    if memory_capsule_enabled:
        from kernel_stateframe_memory_capsule import CAPSULE_HEADER_PREFIX
        capsule_prefix = CAPSULE_HEADER_PREFIX
    pinned_references = {str(value) for value in pinned_references if value}
    for message in prepared:
        if pinned_references and any(ref in str(message.get("content") or "")
                                     for ref in pinned_references):
            _fit_requested_message(message)
    if token_estimate({"messages": prepared, "tools": tools}) <= ceiling_tokens:
        return prepared, optional_changed

    pinned = [message for index, message in enumerate(prepared)
              if _is_pinned_render_message(
                  message, index, pinned_references,
                  memory_capsule_enabled=memory_capsule_enabled)]
    # Optional blocks are removed first.  ``pinned`` includes the latest
    # assistant/tool exchange, current source, disposition/failure facts, and
    # the requested retained read, so none can be replaced by the reread hint.
    retained = pinned
    omitted = len(retained) != len(prepared) or optional_changed

    def estimate() -> int:
        return token_estimate({"messages": retained, "tools": tools})

    # If a pinned read itself is large, make its line-ranged excerpt smaller;
    # it remains present even when the ceiling is unusually small.
    while estimate() > ceiling_tokens:
        candidates = [message for message in pinned
                      if (not memory_capsule_enabled
                          or not str(message.get("content") or "").startswith(
                              capsule_prefix))
                      and str(message.get("content") or "").startswith(
                          ("[StateFrame]", "[Continuation]", "[Working source:",
                           "[Current source:",
                           "[WORK RECORD]",
                           "[Requested retained read", "[WORKING_VIEW"))]
        if not candidates:
            break
        candidate = max(candidates, key=lambda message: len(str(message.get("content") or "")))
        text = str(candidate.get("content") or "")
        if memory_capsule_enabled:
            clipped = _clip_render_text(text, max(160, (len(text) * 3) // 4))
            if clipped == text:
                break
            candidate["content"] = clipped
        else:
            candidate["content"] = _clip_render_text(
                text, max(160, (len(text) * 3) // 4))
    if omitted:
        notice = {"role": "user", "content": _RENDER_OMISSION_NOTICE}
        retained.append(notice)
        while estimate() > ceiling_tokens:
            candidates = [message for message in pinned
                          if (not memory_capsule_enabled
                              or not str(message.get("content") or "").startswith(
                                  capsule_prefix))
                          and str(message.get("content") or "").startswith(
                              ("[StateFrame]", "[Continuation]", "[Working source:",
                               "[Current source:",
                               "[Requested retained read", "[WORKING_VIEW"))]
            if not candidates:
                break
            candidate = max(candidates, key=lambda message: len(str(message.get("content") or "")))
            text = str(candidate.get("content") or "")
            if memory_capsule_enabled:
                clipped = _clip_render_text(text, max(160, (len(text) * 3) // 4))
                if clipped == text:
                    break
                candidate["content"] = clipped
            else:
                candidate["content"] = _clip_render_text(
                    text, max(160, (len(text) * 3) // 4))
    return retained, omitted


_UNKNOWN_WORKING_VIEW_VALUE = "UNKNOWN (not recorded)"


def self_edit_view_mode() -> str:
    """Return the strictly validated host-observed self-edit presentation mode."""
    value = os.environ.get("STATEFRAME_SELF_EDIT_VIEW", "off")
    if value not in {"off", "on"}:
        raise ValueError("STATEFRAME_SELF_EDIT_VIEW must be off or on")
    return value


def _compact_unified_diff(before: str | None, after: str | None, path: str,
                          limit: int = 40) -> str:
    """Render a bounded diff from host-observed file contents."""
    before_lines = [] if before is None else before.splitlines()
    after_lines = [] if after is None else after.splitlines()
    lines = list(difflib.unified_diff(
        before_lines, after_lines, fromfile="a/" + path, tofile="b/" + path,
        n=1, lineterm=""))
    if not lines:
        lines = [f"--- a/{path}", f"+++ b/{path}", "@@ no textual change @@"]
    limit = max(2, limit)
    if len(lines) > limit:
        lines = lines[:limit - 1] + ["[... diff truncated ...]"]
    return "\n".join(lines)


def _render_self_edit_changes(changes: object, edit_views: Sequence[Mapping[str, object]],
                              *, include_applied_diff: bool = True,
                              delivered_diff_steps: set[int] | None = None) -> list:
    """Replace model-intent presentation only when a host edit record exists."""
    if not isinstance(changes, Sequence) or isinstance(changes, (str, bytes)):
        return []
    by_step = {item.get("step"): item for item in edit_views
               if isinstance(item, Mapping)}
    rendered = []
    for change in changes:
        row = copy.deepcopy(change)
        if not isinstance(row, dict) or row.get("observed_result") != "APPLIED":
            rendered.append(row)
            continue
        view = by_step.get(row.get("step"))
        if not isinstance(view, Mapping):
            rendered.append(row)
            continue
        row.pop("stated_intent", None)
        for key in ("authority", "author", "path", "diff", "revision"):
            if key in view and (key != "diff" or include_applied_diff):
                row[key] = copy.deepcopy(view[key])
        # A render is not final-wire delivery.  Keep the host diff replayable
        # until the serialized request-submission owner acknowledges it.
        if not include_applied_diff:
            row.pop("diff", None)
        rendered.append(row)
    return rendered


def _hypothesis_confirms_fix(claim: object) -> bool:
    """Recognize only claims that a current green check can confirm."""
    if not isinstance(claim, str):
        return False
    text = " ".join(claim.lower().split())
    if re.search(r"\b(?:not|never|unclear|whether|maybe|might|could)\b.{0,24}"
                 r"\b(?:pass(?:es|ed|ing)?|green|succeed(?:s|ed|ing)?)\b", text):
        return False
    passing = (r"\b(?:test|tests|check|checks|suite|verification|acceptance)\b"
               r".{0,80}\b(?:pass(?:es|ed|ing)?|green|succeed(?:s|ed|ing)?)\b")
    passing_reverse = (r"\b(?:pass(?:es|ed|ing)?|green|succeed(?:s|ed|ing)?)\b"
                       r".{0,80}\b(?:test|tests|check|checks|suite|verification|acceptance)\b")
    state = (r"\b(?:fix|patch|change|correction|bug|defect|issue)\b"
             r".{0,80}\b(?:already\s+)?(?:in place|applied|fixed|correct|complete|"
             r"implemented|resolved|done|satisfied)\b")
    state_reverse = (r"\b(?:already\s+)?(?:in place|applied|fixed|correct|complete|"
                     r"implemented|resolved|done|satisfied)\b.{0,80}\b(?:fix|patch|"
                     r"change|correction|bug|defect|issue)\b")
    return bool(re.search(passing, text) or re.search(passing_reverse, text)
                or re.search(state, text) or re.search(state_reverse, text))


def _recorded_revision(frame: Mapping[str, object], path: str | None = None) -> object:
    revisions = frame.get("artifact_revisions")
    if isinstance(revisions, Mapping):
        if path is not None and revisions.get(path) is not None:
            return revisions[path]
        values = list(revisions.values())
        if len(values) == 1:
            return values[0]
    for key in ("current_revision", "revision", "product_revision"):
        if frame.get(key) is not None:
            return frame[key]
    binding = frame.get("binding")
    if isinstance(binding, Mapping):
        for key in ("current_revision", "revision", "product_revision"):
            if binding.get(key) is not None:
                return binding[key]
    return None


def _current_public_check_is_green(frame: Mapping[str, object], current_revision: object = None) -> bool:
    contract = frame.get("completion_contract")
    required = (contract.get("required_public_checks", ())
                if isinstance(contract, Mapping) else frame.get("required_public_checks", ()))
    events = []
    for key in ("test_receipts", "recent_test_feedback", "probe_receipts", "receipts"):
        value = frame.get(key)
        if isinstance(value, Mapping):
            value = list(value.values())
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
            events.extend(row for row in value if isinstance(row, Mapping))
    return evaluate_required_tests(frame, required, events).state == SATISFIED


_HYPOTHESIS_PLAN_PREFIX = re.compile(
    r"^\s*(?:(?:now|then)\s*[,;:]?\s*)?"
    r"(?:let\s+me\b|let['’]s\b|i['’]ll\b|i\s+will\b|"
    r"i(?:['’]m|\s+am)\s+going\s+to\b|next\s*,?\s+i\b|first\s*,?\s+i\b|"
    r"i\s+need\s+to\b|i\s+should\b|(?:run|read|check|fix)\b)",
    re.IGNORECASE,
)


def _hypothesis_claim(value: object) -> str:
    if isinstance(value, Mapping):
        for key in ("claim", "text", "content", "statement", "intent"):
            claim = value.get(key)
            if isinstance(claim, str):
                return claim
        return ""
    return value if isinstance(value, str) else ""


def _hypothesis_step(value: object) -> int | None:
    if not isinstance(value, Mapping):
        return None
    for key in ("step", "frame_step", "recorded_step", "test_step", "test_turn", "turn"):
        step = value.get(key)
        if type(step) is int:
            return step
        if isinstance(step, str) and step.isdigit():
            return int(step)
    return None


def _is_hypothesis_plan(value: object) -> bool:
    claim = " ".join(_hypothesis_claim(value).split())
    return bool(claim and _HYPOTHESIS_PLAN_PREFIX.match(claim))


def _recorded_check_revision(value: object) -> object:
    if not isinstance(value, Mapping):
        return None
    for key in ("revision", "current_revision", "product_revision", "binding_revision"):
        if value.get(key) is not None:
            return value[key]
    for key in ("binding", "after_binding", "current_binding", "revision_binding_state"):
        revision = _recorded_check_revision(value.get(key))
        if revision is not None:
            return revision
    return None


def _green_check_step(frame: Mapping[str, object], current_revision: object) -> int | None:
    if not _current_public_check_is_green(frame, current_revision):
        return None

    def green_step(value: object) -> int | None:
        if not isinstance(value, Mapping):
            return None
        status = value.get("status", value.get("result"))
        exit_code = value.get("exit") if "exit" in value else value.get("exit_code")
        is_green = (isinstance(status, str) and status.upper() in {
            "GREEN", "CERTIFIED", "PASSED", "PASS", "SUCCESS", "REUSED_VERIFICATION",
        }) or exit_code == 0
        if not is_green:
            return None
        if (_recorded_check_revision(value) is not None and current_revision is not None
                and _recorded_check_revision(value) != current_revision):
            return None
        return _hypothesis_step(value)

    candidates: list[int] = []
    contract = frame.get("completion_contract")
    checks = contract.get("current_public_checks") if isinstance(contract, Mapping) else None
    for value in (checks, frame.get("verification"), frame.get("last_action")):
        step = green_step(value)
        if step is not None:
            candidates.append(step)
    feedback = frame.get("recent_test_feedback")
    if isinstance(feedback, Sequence) and not isinstance(feedback, (str, bytes)):
        for value in feedback:
            step = green_step(value)
            if step is not None:
                candidates.append(step)
    world = frame.get("world")
    if isinstance(world, Mapping):
        step = green_step(world.get("last_test"))
        if step is not None:
            candidates.append(step)
    if candidates:
        return max(candidates)
    return _hypothesis_step(frame)


def _filter_hypotheses_not_facts(
    frame: Mapping[str, object], *, source_frame: Mapping[str, object] | None = None,
    current_revision: object = None,
) -> tuple[dict, int]:
    """Remove stale model plans from the already-built operational section."""
    public = copy.deepcopy(dict(frame))
    # Typed work is a separate host-owned continuity channel.  Carry it through
    # the operational projection explicitly so plan-shaped hypotheses remain
    # disposable without making the work record disposable too.
    source = source_frame if isinstance(source_frame, Mapping) else frame
    if isinstance(source.get("work_record"), Mapping):
        public["work_record"] = copy.deepcopy(source["work_record"])
    try:
        from kernel_hypothesis_projection import enabled as hypothesis_projection_enabled, project_frame
        if hypothesis_projection_enabled():
            public = project_frame(
                public, current_revision=current_revision, evidence_frame=source)
    except ImportError:
        pass
    frame_clarity = False
    try:
        from kernel_frame_clarity import drop_stale_hypotheses, enabled as frame_clarity_enabled
        frame_clarity = frame_clarity_enabled()
        if frame_clarity:
            public = drop_stale_hypotheses(public)
    except ImportError:
        pass
    from kernel_model_profile import hypothesis_filter_relaxed
    if hypothesis_filter_relaxed():
        values = public.get("hypotheses_not_facts")
        if not isinstance(values, Sequence) or isinstance(values, (str, bytes)):
            values = source.get("hypotheses", source.get("hypotheses_not_facts", ()))
        if isinstance(values, Sequence) and not isinstance(values, (str, bytes)):
            public["hypotheses_not_facts"] = copy.deepcopy(list(values))
        public.pop("hypotheses_not_facts_omitted", None)
        if frame_clarity:
            public = drop_stale_hypotheses(public)
        return public, 0
    values = public.get("hypotheses_not_facts")
    if not isinstance(values, Sequence) or isinstance(values, (str, bytes)):
        public.pop("hypotheses_not_facts_omitted", None)
        if frame_clarity:
            public = drop_stale_hypotheses(public)
        return public, 0
    source_values = source.get("hypotheses")
    if not isinstance(source_values, Sequence) or isinstance(source_values, (str, bytes)):
        source_values = source.get("hypotheses_not_facts")
    source_tail = (list(source_values)[-len(values):]
                   if isinstance(source_values, Sequence) and not isinstance(source_values, (str, bytes))
                   else [])
    green_step = _green_check_step(source, current_revision)
    kept = []
    omitted = 0
    for index, item in enumerate(values):
        recorded = source_tail[index] if index < len(source_tail) else item
        step = _hypothesis_step(recorded)
        before_green = green_step is not None and step is not None and step < green_step
        if _is_hypothesis_plan(item) or _is_hypothesis_plan(recorded) or before_green:
            omitted += 1
        else:
            kept.append(item)
    public["hypotheses_not_facts"] = kept
    if omitted:
        public["hypotheses_not_facts_omitted"] = f"{omitted} earlier planning notes omitted"
    else:
        public.pop("hypotheses_not_facts_omitted", None)
    if frame_clarity:
        public = drop_stale_hypotheses(public)
    return public, omitted


def _has_current_applied_change(changes: object, path: str) -> bool:
    if not isinstance(changes, Sequence) or isinstance(changes, (str, bytes)):
        return False
    for change in changes:
        if not isinstance(change, Mapping) or change.get("observed_result") != "APPLIED":
            continue
        paths = [change.get("path")]
        files = change.get("changed_files")
        if isinstance(files, Sequence) and not isinstance(files, (str, bytes)):
            paths.extend(item.get("path") for item in files if isinstance(item, Mapping))
        if path in paths:
            return True
    return False


def _apply_self_edit_public_view(frame: Mapping[str, object], path: str,
                                 current_revision: object,
                                 edit_views: Sequence[Mapping[str, object]] = (),
                                 *, enabled: bool | None = None,
                                 delivered_diff_steps: set[int] | None = None) -> dict:
    """Apply the opt-in host-observed view to a model-facing frame copy."""
    if enabled is None:
        enabled = self_edit_view_mode() == "on"
    if not enabled:
        return copy.deepcopy(dict(frame))
    public = copy.deepcopy(dict(frame))
    frame_clarity = False
    try:
        from kernel_frame_clarity import enabled as frame_clarity_enabled
        frame_clarity = frame_clarity_enabled()
    except ImportError:
        pass
    if "recent_changes" in public:
        public["recent_changes"] = _render_self_edit_changes(
            public["recent_changes"], edit_views,
            delivered_diff_steps=delivered_diff_steps)
    views_by_step = {item.get("step"): item for item in edit_views
                     if isinstance(item, Mapping)}
    last_action = public.get("last_action")
    if (isinstance(last_action, dict) and last_action.get("result") == "APPLIED"
            and last_action.get("tool") in {"str_replace", "edit", "file_create"}):
        if views_by_step.get(last_action.get("step")) is not None:
            last_action.pop("stated_intent", None)
    from kernel_model_profile import hypothesis_filter_relaxed
    if (not hypothesis_filter_relaxed()
            and _current_public_check_is_green(public, current_revision)):
        for key in ("hypotheses", "hypotheses_not_facts"):
            values = public.get(key)
            if isinstance(values, Sequence) and not isinstance(values, (str, bytes)):
                public[key] = [item for item in values
                               if not _hypothesis_confirms_fix(
                                   item.get("claim") if isinstance(item, Mapping) else item)]
    public.pop("objective", None)
    if _has_current_applied_change(public.get("recent_changes"), path):
        if frame_clarity:
            from kernel_frame_clarity import current_source_alias
            public["objective_reconciliation"] = (
                "The objective describes the ORIGINAL defect; source "
                f"{current_source_alias(public, path, current_revision)} includes your applied "
                "change(s) listed above.")
        else:
            revision = current_revision if current_revision is not None else "UNKNOWN"
            public["objective_reconciliation"] = (
                "The objective describes the ORIGINAL defect; the current revision "
                f"{revision} includes your applied change(s) listed above.")
    return public


def _dedupe_continuation_objective(content: object) -> object:
    """Remove continuation objective copies while preserving its recorded state."""
    if not isinstance(content, str) or not content.startswith("[Continuation]\n"):
        return content
    try:
        value = json.loads(content.split("\n", 1)[1])
    except (IndexError, TypeError, ValueError):
        return content
    changed = False
    if isinstance(value, dict):
        for key in ("active", "parent"):
            item = value.get(key)
            if isinstance(item, dict) and "objective" in item:
                item.pop("objective")
                changed = True
    if not changed:
        return content
    return "[Continuation]\n" + json.dumps(value, ensure_ascii=False, sort_keys=True)


def _working_view_value(value: object) -> str:
    """Render a recorded value without turning absence into a host claim."""
    if value is None:
        return _UNKNOWN_WORKING_VIEW_VALUE
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True,
                          separators=(",", ":"))
    except (TypeError, ValueError):
        return _UNKNOWN_WORKING_VIEW_VALUE


def _working_view_action(last_action: object) -> tuple[str, str]:
    """Return only the recorded action identity and bounded public parameters."""
    if not isinstance(last_action, Mapping):
        return _UNKNOWN_WORKING_VIEW_VALUE, _UNKNOWN_WORKING_VIEW_VALUE
    tool = _working_view_value(last_action.get("tool"))
    parameters = last_action.get("parameters")
    if not isinstance(parameters, Mapping):
        return tool, _UNKNOWN_WORKING_VIEW_VALUE
    try:
        short_args = json.dumps(dict(parameters), ensure_ascii=False, sort_keys=True,
                                separators=(",", ":"))
    except (TypeError, ValueError):
        short_args = _UNKNOWN_WORKING_VIEW_VALUE
    if len(short_args) > 500:
        short_args = short_args[:497] + "..."
    return tool, short_args


def _working_view_passage(capture: object) -> str:
    """Tail-bound the exact prior response fields; never summarize them."""
    if isinstance(capture, Mapping):
        message = capture.get("message") if isinstance(capture.get("message"), Mapping) else capture
        reasoning = message.get("response_reasoning_content", message.get("reasoning_content"))
        content = message.get("response_content", message.get("content"))
    else:
        reasoning = getattr(capture, "response_reasoning_content", None)
        content = getattr(capture, "response_content", None)

    def tail(value: object, limit: int) -> str:
        if not isinstance(value, str):
            return _UNKNOWN_WORKING_VIEW_VALUE
        omitted = max(0, len(value) - limit)
        if omitted:
            return f"[...truncated {omitted} chars]\n" + value[-limit:]
        return value

    return tail(reasoning, 2000) + "\n" + tail(content, 500)


def stateframe_work_note_mode() -> str:
    """Return the validated opt-in flattened continuation-note switch."""
    value = os.environ.get("STATEFRAME_WORK_NOTE", "off")
    if value not in {"off", "on"}:
        raise ValueError("STATEFRAME_WORK_NOTE must be off or on")
    return value


def stateframe_native_last_mode() -> str:
    """Return the validated opt-in native-last-exchange switch."""
    value = os.environ.get("STATEFRAME_NATIVE_LAST", "off")
    if value not in {"off", "on"}:
        raise ValueError("STATEFRAME_NATIVE_LAST must be off or on")
    return value


def _response_fields(capture: object) -> tuple[object, object]:
    """Read the exact response fields retained by RequestCapture.

    RequestCapture populates these fields from the ``response_received`` event;
    this helper also accepts the event-shaped mapping used by offline probes.
    """
    if isinstance(capture, Mapping):
        message = capture.get("message")
        if not isinstance(message, Mapping):
            response = capture.get("response")
            choices = response.get("choices") if isinstance(response, Mapping) else None
            first = choices[0] if isinstance(choices, Sequence) and choices else None
            message = first.get("message") if isinstance(first, Mapping) else capture
        reasoning = message.get("response_reasoning_content",
                               message.get("reasoning_content"))
        content = message.get("response_content", message.get("content"))
        return content, reasoning
    return (getattr(capture, "response_content", None),
            getattr(capture, "response_reasoning_content", None))


def _latest_decision_text(value: str, limit: int = 700) -> str:
    """Carry an explicit latest decision instead of an opening action preamble."""
    paragraphs = [part.strip() for part in re.split(r"\n\s*\n", value.strip()) if part.strip()]
    for paragraph in reversed(paragraphs):
        marker = re.search(r"^\s*decision\s*[:\-]", paragraph, re.IGNORECASE)
        if marker is not None:
            return paragraph[marker.start():][-limit:]
    return ""


def _tokenlab_reasoning_tail(reasoning: str, mode: str) -> str:
    """Exact model text, no summarization: `tail` = the closing paragraphs (<= 700 chars),
    `full` = the whole reasoning of the latest response (<= 8000 chars, tail-kept)."""
    text = reasoning.strip()
    decision = _latest_decision_text(text)
    if decision:
        return decision
    if mode == "full":
        return text[-8000:]
    paragraphs = [part.strip() for part in re.split(r"\n\s*\n", text) if part.strip()]
    kept: list[str] = []
    size = 0
    for part in reversed(paragraphs):
        if kept and size + len(part) > 700:
            break
        kept.insert(0, part[-700:])
        size += len(part)
    return "\n\n".join(kept)


def _tokenlab_conclusion(handoff: object, capture: object, journal: object = None) -> object:
    """request fitting (L3a): carry the model's own latest reasoning conclusion across the F4 cut.

    Labelled as the model's prior assessment written BEFORE the latest tool outcome; host
    results in the frame stay authoritative.  Off (default) returns the handoff unchanged."""
    mode = os.environ.get("STATEFRAME_TOKENLAB_HANDOFF_CONCLUSION", "off").strip().lower()
    if mode not in {"tail", "full"} or not isinstance(handoff, Mapping):
        return handoff
    _content, reasoning = _response_fields(capture)
    if not isinstance(reasoning, str) or not reasoning.strip():
        return handoff
    carried = _tokenlab_reasoning_tail(reasoning, mode)
    if not carried:
        return handoff
    result = dict(handoff)
    result["content"] = (str(result.get("content") or "") + "\n[Your own reasoning from the previous "
                         "response, written before its tool result; host results in this frame are "
                         "authoritative]\n" + carried)
    try:
        from kernel_stateframe_f4 import token_estimate
        result["token_estimate"] = token_estimate({"role": "user", "content": result["content"]})
    except (ImportError, TypeError, ValueError):
        pass
    emit = getattr(journal, "emit", None)
    if callable(emit):
        try:
            emit("engine_conclusion_carried", producer="engine", dispatch=False,
                 mode=mode, chars=len(carried))
        except (AttributeError, TypeError, ValueError):
            pass
    return result


def _continuation_intent(capture: object) -> str | None:
    """Capture one bounded, model-written intent without model summarization."""
    content, reasoning = _response_fields(capture)
    for candidate in (content, reasoning):
        if isinstance(candidate, str) and candidate.strip():
            decision = _latest_decision_text(candidate)
            if decision:
                return decision[-400:]
    if isinstance(content, str) and content.strip():
        return content.strip()[-400:]
    if isinstance(reasoning, str) and reasoning.strip():
        paragraphs = [paragraph.strip() for paragraph in re.split(
            r"\n\s*\n", reasoning.strip()) if paragraph.strip()]
        if paragraphs:
            return paragraphs[-1][:300]
    return None


def _last_native_exchange(messages: Sequence[Mapping[str, object]]) -> tuple[dict, dict] | None:
    """Return the last actual assistant/tool exchange, with private reasoning removed.

    The live worker normalizes one selected tool call into one assistant/tool
    pair.  Matching the result ID also keeps this safe for a native batch whose
    provider assistant message contained several calls.
    """
    if not isinstance(messages, Sequence) or isinstance(messages, (str, bytes)):
        return None
    for index in range(len(messages) - 1, 0, -1):
        raw_result = messages[index]
        if (not isinstance(raw_result, Mapping) or raw_result.get("role") != "tool"):
            continue
        assistant_index = index - 1
        while (assistant_index >= 0 and isinstance(messages[assistant_index], Mapping)
               and messages[assistant_index].get("role") == "tool"):
            assistant_index -= 1
        raw_assistant = messages[assistant_index] if assistant_index >= 0 else None
        if (not isinstance(raw_assistant, Mapping)
                or raw_assistant.get("role") != "assistant"):
            continue
        result_id = raw_result.get("tool_call_id")
        calls = raw_assistant.get("tool_calls")
        if (not isinstance(result_id, str) or not isinstance(calls, Sequence)
                or isinstance(calls, (str, bytes))):
            continue
        matching = next((call for call in calls
                         if isinstance(call, Mapping) and call.get("id") == result_id), None)
        if matching is None:
            continue
        assistant = copy.deepcopy(dict(raw_assistant))
        assistant.pop("reasoning_content", None)
        assistant.pop("response_reasoning_content", None)
        # The live worker answers one selected call per turn.  Keep the actual
        # wire call shape while narrowing a provider-side batch to that closed
        # call/result pair.
        assistant["tool_calls"] = [copy.deepcopy(dict(matching))]
        result = copy.deepcopy(dict(raw_result))
        pair = (assistant, result)
        try:
            assert_no_orphaned_tool_result(pair)
        except AssertionError:
            continue
        return pair
    return None


def _compact_native_call(assistant: Mapping[str, object]) -> str:
    """Render the actual call identity and compact arguments for the note."""
    calls = assistant.get("tool_calls")
    call = calls[0] if isinstance(calls, Sequence) and calls else {}
    function = call.get("function") if isinstance(call, Mapping) else None
    function = function if isinstance(function, Mapping) else {}
    name = str(function.get("name") or "UNKNOWN")
    raw_arguments = function.get("arguments", "{}")
    try:
        arguments = json.loads(raw_arguments) if isinstance(raw_arguments, str) else raw_arguments
        compact = json.dumps(arguments, ensure_ascii=False, sort_keys=True,
                              separators=(",", ":"))
    except (TypeError, ValueError, json.JSONDecodeError):
        compact = str(raw_arguments)
    if len(compact) > 500:
        compact = compact[:497] + "..."
    return f"{name}({compact})"


def _continuation_messages(capture: object,
                           messages: Sequence[Mapping[str, object]]) -> tuple[dict | None, tuple[dict, dict] | None]:
    """Build the two opt-in presentations from one actual prior exchange."""
    native = _last_native_exchange(messages)
    intent = _continuation_intent(capture)
    if intent is None or native is None:
        return None, native
    result_text = native[1].get("content")
    result_text = result_text if isinstance(result_text, str) else str(result_text or "")
    note = {
        "role": "user",
        "content": (
            "[Your previous step — model-written, may be revised if contradicted]\n"
            + intent + "\n"
            + "You then called: " + _compact_native_call(native[0]) + "\n"
            + "Result: " + result_text[:600]
        ),
    }
    return note, native


def _f4_host_envelope(frame: Mapping[str, object], continuity: object) -> Mapping[str, object]:
    snapshot = continuity.snapshot() if continuity is not None else {}
    if isinstance(snapshot, Mapping) and isinstance(snapshot.get("host_envelope"), Mapping):
        return snapshot["host_envelope"]
    envelope = frame.get("host_envelope")
    return envelope if isinstance(envelope, Mapping) else {}


def _model_frame_facts(
    frame: Mapping[str, object], *, unified: bool = False,
    retained_evidence: Sequence[Mapping[str, object]] = (),
    gear_projection: Mapping[str, object] | None = None,
) -> str:
    """Serialize model-facing facts without duplicating the boot sidecar."""
    facts_frame = copy.deepcopy(dict(gear_projection if gear_projection is not None else frame))
    # The bounded memory presentation is sent as its own provider message;
    # remove only its v2 host metadata when that opt-in arm is active.  The
    # OFF path must retain any pre-existing field byte-for-byte.
    if _memory_capsule_wire_enabled():
        from kernel_stateframe_memory_capsule import CAPSULE_FRAME_FIELD
        facts_frame.pop(CAPSULE_FRAME_FIELD, None)
    display_truth = False
    display_source = copy.deepcopy(facts_frame)
    try:
        from kernel_frame_display_truth import enabled as display_truth_enabled
        display_truth = display_truth_enabled()
    except ImportError:
        pass
    if gear_projection is not None:
        # The gear projection has already selected the public fields. Running
        # legacy redaction/dedup projections over it would rebuild lazy
        # machinery or erase its explicit coverage markers.
        # The boot capsule is delivered by its pinned advisory sidecar.  A
        # projection supplied by a gear/frame-budget arm must not reintroduce
        # the persisted packet as a second model-facing copy.
        facts_frame.pop("boot_packet", None)
        if display_truth:
            from kernel_frame_display_truth import project_frame
            facts_frame = project_frame(facts_frame)
        rendered = "[StateFrame]\n" + canonical_bytes(facts_frame).decode()
        try:
            from kernel_hypothesis_projection import append_block
            rendered = append_block(rendered, facts_frame)
        except ImportError:
            pass
        return rendered
    from kernel_frame_edit_integrity import enabled as frame_integrity_enabled, project_frame_results
    if frame_integrity_enabled():
        facts_frame = project_frame_results(facts_frame)
    from kernel_completion_status import enabled as blocker_render_enabled, presentation_frame
    if blocker_render_enabled():
        facts_frame = presentation_frame(facts_frame)
    frame_clarity = False
    try:
        from kernel_frame_clarity import enabled as frame_clarity_enabled, project_model_frame
        frame_clarity = frame_clarity_enabled()
        if frame_clarity:
            facts_frame = project_model_frame(facts_frame, retained_evidence=retained_evidence)
    except ImportError:
        pass
    facts_frame.pop("boot_packet", None)
    # The typed record is delivered as its own pinned block below.  Do not
    # duplicate it inside the JSON facts projection.
    facts_frame.pop("work_record", None)
    facts_frame.pop("decision_cache", None)
    from kernel_sweep_fixes import enabled as sweep_fixes_enabled
    if sweep_fixes_enabled():
        # Public-test projection remains evidence in the host journal, not a
        # second model-facing completion verdict.
        facts_frame.pop("completion_verdict", None)
    if unified:
        # The unified block owns these projections; keeping their JSON copies
        # here would recreate the very duplicate MAP/boot state it replaces.
        facts_frame.pop("stateframe_v2_s1", None)
        facts_frame.pop("decision_state", None)
    from kernel_stateframe_dedup import enabled as dedup_enabled, project_frame
    if os.environ.get("STATEFRAME_HOST_FACTS", "off") == "on":
        # The canonical host-facts block owns the joined control state.  Keep
        # the raw frame available to the host journal, but do not expose a
        # second copy of its ticket, obligation, or completion prose.
        from kernel_host_facts import suppress_redundant_frame_fields
        facts_frame = suppress_redundant_frame_fields(facts_frame, mode="on")
    if dedup_enabled():
        facts_frame = project_frame(facts_frame, retained_evidence=retained_evidence)
    if display_truth:
        from kernel_frame_display_truth import project_frame
        # ``source_frame`` retains the pre-clarity identities so a clarity
        # projection cannot collapse a historical W0 row into current W1.
        facts_frame = project_frame(facts_frame, source_frame=display_source)
    rendered = "[StateFrame]\n" + canonical_bytes(facts_frame).decode()
    if frame_clarity and not display_truth:
        from kernel_frame_clarity import project_serialized_stateframe
        rendered = project_serialized_stateframe(rendered)
    try:
        from kernel_hypothesis_projection import append_block
        rendered = append_block(rendered, facts_frame)
    except ImportError:
        pass
    return rendered


def _blocker_completion_status(frame: Mapping[str, object]):
    """Return the opt-in reducer status, or ``None`` on the legacy arm."""
    from kernel_completion_status import completion_status_from_frame, enabled
    return completion_status_from_frame(frame) if enabled() else None


def _blocker_terminal_allowed(frame: Mapping[str, object]) -> bool:
    status = _blocker_completion_status(frame)
    return status is None or status.state == "ACCEPTABLE"


def _retained_source_block(evidence: Mapping[str, object], *, label: str) -> str:
    """Render retained bytes with the opt-in compact header only."""
    from kernel_source_presentation import source_block
    from kernel_stateframe_dedup import (
        RETAINED_SOURCE_METADATA_FIELDS, enabled as dedup_enabled,
    )
    if dedup_enabled():
        return source_block(evidence, label=label,
                            metadata_keys=RETAINED_SOURCE_METADATA_FIELDS)
    return source_block(evidence, label=label)


def _working_view_decision_state(frame: Mapping[str, object]) -> list[str]:
    """Render only bounded decision facts already recorded in the frame."""
    try:
        from kernel_stateframe_f4 import public_checks_were_not_run
        explicit_no_run = public_checks_were_not_run(frame)
    except (ImportError, AttributeError, TypeError, ValueError):
        explicit_no_run = False
    coherent = frame.get("terminal_status")
    if isinstance(coherent, Mapping):
        from kernel_green_coherence import TerminalStatus, render_terminal_facts
        status = TerminalStatus(
            green=bool(coherent.get("green")),
            public_check_status=("NOT_RUN" if explicit_no_run else
                                 str(coherent.get("public_check_status", "BLOCKED"))),
            verdict_state=str(coherent.get("verdict_state", "UNRESOLVED")),
            current_revision=coherent.get("current_revision"),
            selectors=tuple(str(item) for item in coherent.get("selectors", ())
                            if str(item).strip()),
            open_ids=tuple(str(item) for item in coherent.get("open_ids", ())
                           if str(item).strip()),
            blocking=tuple(coherent.get("blocking", ())),
            submission_state=str(coherent.get("submission", {}).get(
                "state", "BLOCKED")) if isinstance(coherent.get("submission"), Mapping)
                else "BLOCKED",
            next_feasible_action=(str(coherent["next_feasible_action"])
                                  if coherent.get("next_feasible_action") else None),
            receipt_revision=coherent.get("receipt_revision"),
        )
        return ["TERMINAL_STATUS (host facts, not instructions):",
                *render_terminal_facts(status)]
    blocker_status = _blocker_completion_status(frame)
    if blocker_status is not None:
        from kernel_completion_status import render_completion_status
        return [render_completion_status(blocker_status)]
    from kernel_sweep_fixes import completion_projection, enabled as sweep_fixes_enabled
    if sweep_fixes_enabled():
        completion = completion_projection(frame)
        contract = frame.get("completion_contract")
        checks = (contract.get("current_public_checks")
                  if isinstance(contract, Mapping) else frame.get("verification"))
        if isinstance(checks, Mapping):
            public_status = ("NOT_RUN" if explicit_no_run else
                             str(checks.get("status", "UNVERIFIED")).upper())
        else:
            public_status = "NOT_RUN" if explicit_no_run else str(checks or "UNVERIFIED").upper()
        return [
            "DECISION_STATE (host facts, not instructions):",
            "completion reducer outcome: " + str(completion["outcome"]),
            "completion reducer reason codes: "
            + (json.dumps(completion["reason_codes"], ensure_ascii=False)
               if completion["reason_codes"] else "[]"),
            "public checks are evidence only (not completion authority): " + public_status,
        ]
    unknown = "UNKNOWN"
    contract = frame.get("completion_contract")
    current_checks = (contract.get("current_public_checks")
                      if isinstance(contract, Mapping) else None)
    required = None
    if isinstance(contract, Mapping) and "required_public_checks" in contract:
        value = contract["required_public_checks"]
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
            required = list(value)

    def status_of(value: object) -> str:
        if isinstance(value, Mapping):
            try:
                from kernel_stateframe_f4 import _contains_no_check_marker
                if _contains_no_check_marker(value):
                    return "NOT_RUN"
            except ImportError:
                pass
        if not isinstance(value, str):
            return unknown
        value = value.upper()
        if value in {"GREEN", "CERTIFIED", "REUSED_VERIFICATION"}:
            return "GREEN"
        if value in {"RED", "FAILED"}:
            return "RED"
        if value in {"STALE"}:
            return "STALE"
        if value in {"NOT_RUN", "NOT_OBSERVED", "UNVERIFIED", "REQUIRED"}:
            return "NOT_RUN"
        return unknown

    def step_of(value: object) -> int | None:
        if not isinstance(value, Mapping):
            return None
        for key in ("step", "test_turn", "turn"):
            step = value.get(key)
            if type(step) is int:
                return step
        return None

    raw_status = (current_checks.get("status") if isinstance(current_checks, Mapping)
                  and "status" in current_checks else current_checks)
    status = status_of(raw_status)
    green_steps = []
    if status == "GREEN":
        current_step = step_of(current_checks)
        if current_step is not None:
            green_steps.append(current_step)
    feedback = frame.get("recent_test_feedback")
    if isinstance(feedback, Sequence) and not isinstance(feedback, (str, bytes)):
        for record in feedback:
            if not isinstance(record, Mapping) or status_of(record.get("result")) != "GREEN":
                continue
            step = step_of(record)
            if step is not None:
                green_steps.append(step)
    changes = frame.get("recent_changes")
    if status == "STALE":
        changed_after_green = "yes"
    elif not isinstance(changes, Sequence) or isinstance(changes, (str, bytes)):
        changed_after_green = unknown
    elif not changes:
        changed_after_green = "no" if status == "GREEN" or green_steps else unknown
    else:
        change_steps = [step_of(change) for change in changes]
        if not green_steps or any(step is None for step in change_steps):
            changed_after_green = unknown
        else:
            changed_after_green = "yes" if max(change_steps) > max(green_steps) else "no"
    from kernel_empirical_fixes import empirical_mode
    if empirical_mode() == "on":
        from kernel_empirical_fixes import change_after_green_from_frame
        changed_after_green = str(
            frame.get("empirical_change_after_green")
            or change_after_green_from_frame(frame)
        )

    def recorded_revision(value: object) -> object:
        if not isinstance(value, Mapping):
            return None
        for key in ("current_revision", "revision", "product_revision"):
            if value.get(key) is not None:
                return value[key]
        binding = value.get("binding")
        return binding.get("product_revision") if isinstance(binding, Mapping) else None

    checked_revision = recorded_revision(current_checks)
    current_revision = recorded_revision(frame)
    if status == "GREEN":
        revisions = frame.get("artifact_revisions")
        if current_revision is None and isinstance(revisions, Mapping):
            values = list(revisions.values())
            if checked_revision in values:
                current_revision = checked_revision
            elif len(values) == 1:
                current_revision = values[0]
        if (checked_revision is not None and current_revision is not None
                and checked_revision != current_revision):
            status = "STALE"
            changed_after_green = "yes"
        elif changed_after_green == "yes":
            status = "STALE"

    selectors = None
    if isinstance(current_checks, Mapping):
        for key in ("selector", "selectors", "covered_selectors"):
            if key in current_checks:
                selectors = current_checks[key]
                break
    if selectors is None and isinstance(contract, Mapping) and "required_public_checks" in contract:
        selectors = contract["required_public_checks"]
    if isinstance(selectors, str):
        selector_text = selectors
    elif isinstance(selectors, Sequence) and not isinstance(selectors, (str, bytes)):
        try:
            selectors = list(selectors)
            selector_text = (str(selectors[0]) if len(selectors) == 1 else
                             json.dumps(selectors, ensure_ascii=False,
                                        separators=(",", ":")))
        except (TypeError, ValueError):
            selector_text = unknown
    else:
        selector_text = unknown

    def list_text(value: object) -> str:
        if not isinstance(value, Sequence) or isinstance(value, (str, bytes)):
            return unknown
        try:
            return json.dumps(list(value), ensure_ascii=False, separators=(",", ":"))
        except (TypeError, ValueError):
            return unknown

    unmet = None
    if isinstance(current_checks, Mapping):
        for key in ("unmet_public_checks", "missing_selectors"):
            if key in current_checks:
                unmet = list_text(current_checks[key])
                break
    if unmet is None:
        if status == "GREEN":
            unmet = "[]"
        elif status in {"NOT_RUN", "STALE"} and required is not None:
            unmet = list_text(required)
        elif status == "RED" and required is not None and len(required) == 1:
            unmet = list_text(required)
        else:
            unmet = unknown
    host_findings = []
    from kernel_edit_guard import enabled as edit_guard_enabled
    if edit_guard_enabled():
        value = frame.get("host_observed_findings")
        if value is None and isinstance(frame.get("kernel_findings"), Mapping):
            value = frame["kernel_findings"].get("host_observed_findings")
        if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
            host_findings = [str(item) for item in value if str(item).strip()]
    from kernel_completion_disposition import (
        disposition_mode, render_disposition, render_v2_disposition,
    )
    if disposition_mode() == "on":
        return render_disposition(
            frame, status=status, changed_after_green=changed_after_green, unmet=unmet,
            checked_revision=checked_revision, current_revision=current_revision,
        )
    if disposition_mode() == "v2":
        return render_v2_disposition(
            frame, status=status, changed_after_green=changed_after_green, unmet=unmet,
            checked_revision=checked_revision, current_revision=current_revision,
        )
    if status == "GREEN" and changed_after_green == "no" and unmet == "[]" and not host_findings:
        requirements = "SATISFIED"
    else:
        reasons = []
        if status != "GREEN":
            reasons.append("public checks on the CURRENT revision are " + status)
        if changed_after_green != "no":
            reasons.append("last change after last green check: " + changed_after_green)
        if unmet != "[]":
            reasons.append("unmet public checks: " + unmet)
        if host_findings:
            reasons.append("open HOST_OBSERVED findings: " + "; ".join(host_findings))
        requirements = "NOT SATISFIED (" + "; ".join(reasons) + ")"
    return [
        "DECISION_STATE (host facts, not instructions):",
        "public checks on the CURRENT revision: " + status + " (" + selector_text + ")",
        "last change after last green check: " + changed_after_green,
        "unmet public checks: " + unmet,
        "public completion requirements on the CURRENT revision: " + requirements,
    ]


def build_working_view(mode: str, frame: Mapping[str, object], capture: object = None) -> dict:
    """Build the one model-facing working-view message from recorded state only."""
    if mode not in {"facts", "resolved", "actions", "decision", "findings"}:
        raise ValueError("working view message requires facts, resolved, actions, decision or findings mode")
    display_truth = False
    display_frame = frame
    try:
        from kernel_frame_display_truth import enabled as display_truth_enabled, project_frame
        display_truth = display_truth_enabled()
        if display_truth:
            display_frame = project_frame(frame)
    except ImportError:
        pass

    def finish(message: dict, public_frame: Mapping[str, object] | None = None) -> dict:
        if not display_truth:
            return message
        from kernel_frame_display_truth import transform_working_view
        return transform_working_view(
            message, frame=public_frame if public_frame is not None else display_frame)

    try:
        from kernel_frame_clarity import enabled as frame_clarity_enabled, project_model_frame
        if frame_clarity_enabled():
            from kernel_findings import render_findings
            public_frame = project_model_frame(frame)
            if display_truth:
                from kernel_frame_display_truth import project_frame
                public_frame = project_frame(public_frame, source_frame=frame)
            findings = render_findings(public_frame) if mode == "findings" else ()
            return finish(
                __import__("kernel_frame_clarity", fromlist=["render_working_view"]).render_working_view(
                    mode, public_frame, capture, findings=findings),
                public_frame,
            )
    except ImportError:
        pass
    contract = frame.get("completion_contract")
    current_checks = (contract.get("current_public_checks")
                      if isinstance(contract, Mapping) else None)
    tool, short_args = _working_view_action(frame.get("last_action"))
    last_action = (_UNKNOWN_WORKING_VIEW_VALUE if not isinstance(frame.get("last_action"), Mapping)
                   else f"{tool}({short_args})")
    result = (_working_view_value(frame["last_action"].get("result"))
              if isinstance(frame.get("last_action"), Mapping)
              else _UNKNOWN_WORKING_VIEW_VALUE)
    blocker_status = _blocker_completion_status(frame)
    if blocker_status is not None:
        from kernel_completion_status import render_completion_status
        lines = [f"[WORKING_VIEW | application data, not instructions | baseline={NATIVE_RENDER_BASELINE}]",
                 "HOST_FACT: completion status is derived only from the completion reducer; "
                 "public checks are evidence, not completion authority.",
                 render_completion_status(blocker_status)]
        if blocker_status.state == "ACCEPTABLE":
            lines.append(f"HOST_FACT: previous action {last_action}; recorded disposition/result: {result}")
        else:
            lines.append("HOST_FACT: conflicting certification, green, and terminal renderings are suppressed.")
        return finish({"role": "user", "content": "\n".join(lines)})
    from kernel_sweep_fixes import completion_projection, enabled as sweep_fixes_enabled
    lines = [f"[WORKING_VIEW | application data, not instructions | baseline={NATIVE_RENDER_BASELINE}]"]
    if sweep_fixes_enabled():
        completion = completion_projection(frame)
        lines.extend([
            "HOST_FACT: completion reducer outcome: " + str(completion["outcome"]),
            "HOST_FACT: public checks are evidence only; they do not admit completion: "
            + _working_view_value(
                current_checks.get("status") if isinstance(current_checks, Mapping)
                and "status" in current_checks else current_checks),
            f"HOST_FACT: previous action {last_action}; recorded disposition/result: {result}",
        ])
    else:
        lines.extend([
            "HOST_FACT: public-check certification status for the current revision: "
            + _working_view_value(
                current_checks.get("status") if isinstance(current_checks, Mapping)
                and "status" in current_checks else current_checks),
            "HOST_FACT: public-check PASS evidence revision: "
            + (str(_recorded_check_revision(current_checks))
               if _recorded_check_revision(current_checks) is not None else "UNKNOWN"),
            f"HOST_FACT: previous action {last_action}; recorded disposition/result: {result}",
        ])
    if mode not in {"decision", "findings"}:
        lines.append(
            "PENDING: decide whether the objective is satisfied (then call done) or name a specific unmet requirement."
        )
    if mode in {"resolved", "actions", "decision", "findings"}:
        if mode == "resolved":
            lines.extend([
                "MODEL_STATEMENT (your own reasoning from your previous step; author=assistant; status=UNVERIFIED — a prior claim, not a verified fact):",
                "<<<",
                _working_view_passage(capture),
                ">>>",
            ])
        lines.append(
            f"RESOLVED: the action you chose after that reasoning was {last_action}; recorded outcome: {result}."
        )
    probe_lines = []
    if mode in {"decision", "findings"}:
        from kernel_probe_gate import probe_gate_mode, render_probe_findings
        if probe_gate_mode() == "on":
            probe_lines = render_probe_findings(frame)
    if mode == "findings":
        from kernel_findings import render_findings
        quantity_lines = []
        if frame.get("quantity_bindings"):
            from kernel_bind_quantity import bind_quantity_mode, render_quantity_findings
            if bind_quantity_mode() == "on":
                quantity_lines = render_quantity_findings(frame)
        if quantity_lines:
            from kernel_bind_quantity import FINDINGS_TOKEN_CAP, lexical_token_count
            quantity_cost = lexical_token_count("\n".join(quantity_lines))
            lines.extend(render_findings(frame, cap=max(1, FINDINGS_TOKEN_CAP - quantity_cost)))
            lines.extend(quantity_lines)
        else:
            lines.extend(render_findings(frame))
        lines.extend(probe_lines)
    if mode in {"decision", "findings"}:
        if mode == "decision":
            lines.extend(probe_lines)
        lines.extend(_working_view_decision_state(frame))
    return finish({"role": "user", "content": "\n".join(lines)})


def latest_exchange_reasoning_mode() -> str:
    """Return the strictly validated latest-exchange assistant presentation mode."""
    value = os.environ.get("STATEFRAME_LATEST_EXCHANGE_REASONING", "keep")
    if value not in {"keep", "omit"}:
        raise ValueError("STATEFRAME_LATEST_EXCHANGE_REASONING must be keep or omit")
    return value


def _apply_latest_exchange_reasoning(exchange: object, mode: str) -> object:
    """Optionally remove assistant reasoning/prose without changing tool results."""
    if mode != "omit" or exchange is None or getattr(exchange, "mode", None) != "roles":
        return exchange
    messages = []
    for message in exchange.messages:
        if isinstance(message, Mapping) and message.get("role") == "assistant":
            messages.append({
                "role": "assistant",
                "content": "",
                "tool_calls": copy.deepcopy(message.get("tool_calls", [])),
            })
        else:
            messages.append(message)
    return dataclasses.replace(exchange, messages=tuple(messages))


def append_v2_s1_sidecar(messages: Sequence[dict], store: object,
                         *, provider_request: bool = True) -> list[dict]:
    """Append the S1 block to the already-composed provider payload.

    The OFF path returns a copied sequence with no content transformation.  The
    helper is shared by the final prepare path and arm-parity tests.
    """
    from kernel_stateframe_v2_s1 import append_sidecar
    return append_sidecar(messages, store, provider_request=provider_request)


def _boundary_json_payload(value: object) -> tuple[object, list[str]]:
    """Return ``value`` unchanged when it is strict JSON, else a tagged copy.

    Only the boundary-binding journal path uses this.  A strict-JSON payload is
    returned as the SAME object (byte-identical journal); a Python-only leaf
    (Ellipsis, bytes, set, complex, non-finite float, non-string key) becomes
    ``{"$nonjson": "<type>"}`` and its type is reported so the caller can
    journal a warning instead of crashing the run.
    """
    try:
        json.dumps(value, sort_keys=True, allow_nan=False)
        return value, []
    except (TypeError, ValueError):
        pass
    found: list[str] = []

    def tag(item: object) -> object:
        if item is None or isinstance(item, (str, bool, int)):
            return item
        if isinstance(item, float):
            if item == item and item not in (float("inf"), float("-inf")):
                return item
        elif isinstance(item, Mapping):
            result: dict[str, object] = {}
            for key, child in item.items():
                if not isinstance(key, str):
                    found.append("key:" + type(key).__name__)
                    key = "$nonjson_key:" + repr(key)[:64]
                result[key] = tag(child)
            return result
        elif isinstance(item, (list, tuple)):
            return [tag(child) for child in item]
        name = "Ellipsis" if item is Ellipsis else type(item).__name__
        found.append(name)
        return {"$nonjson": name}

    return tag(value), found



def _journal_safe_fields(payload):
    """Rename keys the continuation journal reserves (schema, task_id, ...) to receipt_<key>.

    Receipt dicts are shared with other consumers, so the journal-boundary copy is renamed instead of the source.
    """
    from kernel_continuation_journal import journal_safe_fields

    return journal_safe_fields(payload)


def _authored_rows(records: object, already: object) -> list[object]:
    """Solver-authored check receipts the generic identity filter would drop.

    They carry their own parent/candidate revision binding, which
    ``kernel_obligation_assess.certifying_authored_receipt`` checks against the
    live candidate revision, so they bypass the generic verdict-identity filter.
    """
    seen = {id(item) for item in (already or ())}
    rows: list[object] = []
    for item in records or ():
        provenance = item.get("provenance") if isinstance(item, Mapping) else None
        if (isinstance(provenance, Mapping) and provenance.get("kind") == "AUTHORED_CHECK"
                and id(item) not in seen):
            rows.append(item)
    return rows


def _authored_candidate_revision(runtime: object) -> str | None:
    """The product revision authored checks bind as their candidate (react_repair)."""
    try:
        current = runtime.binding()
    except (AttributeError, OSError, RuntimeError, TypeError, ValueError):
        return None
    if not isinstance(current, Mapping):
        return None
    value = str(current.get("product_revision") or "").strip()
    return value or None


class StateFrameRuntime:
    def __setattr__(self, name: str, value: object) -> None:
        """Keep heuristic stop outcomes advisory while hard budgets remain authoritative."""
        if name == "system_outcome" and value is not None:
            from kernel_terminal_policy import (
                enabled as hard_budget_only_enabled,
                queue_advisory,
                terminal_outcome_permitted,
            )

            if (hard_budget_only_enabled(self)
                    and not terminal_outcome_permitted(value, self)):
                outcome = str(value).strip().lower()
                triggers = {
                    "blocked": "blocked",
                    "catalog_unknown": "catalog_unknown",
                    "completion_owner_exhausted": "completion_owner_exhausted",
                    "effect_boundary_shadow": "effect_boundary_shadow",
                    "green_lock_no_permitted_action": "greenlock_empty_menu",
                    "post_green_stall": "postgreen_stall",
                    "postgreen_no_progress": "postgreen_no_progress",
                    "stalled": "response_reuse_stall",
                    "tool_call_loop_breaker": "tool_call_loop",
                    "stopped_incomplete": "generic_terminal",
                }
                queue_advisory(self, triggers.get(outcome, "generic_terminal"))
                return
        object.__setattr__(self, name, value)

    @profiled_function_span("runtime_initialization")
    def __init__(self, owner: object, *, output: Path, target: Path | None, model: str,
                 tools: object, temperature: float,
                 source_resolver: Callable[[str, str], str | None], step_limit: int | None = 200,
                 multi_file: bool = False, edit_contract: dict | None = None, workspace=None,
                 resume=None, endpoint_profile: object | None = None):
        self.owner = owner
        self.stateframe_micrograph_mode = os.environ.get("STATEFRAME_MICROGRAPH", "off").strip().lower()
        self.micrograph_wire = None
        if self.stateframe_micrograph_mode != "off":
            from kernel_micrograph_wire import MicroGraphWire, mode as micrograph_mode
            self.stateframe_micrograph_mode = micrograph_mode()
            self.micrograph_wire = MicroGraphWire(str(getattr(owner, "task_id", "task")))
        self._lean_base_tools = (
            [copy.deepcopy(dict(tool)) for tool in tools if isinstance(tool, Mapping)]
            if isinstance(tools, Sequence) and not isinstance(tools, (str, bytes, bytearray))
            else None
        )
        self.endpoint_profile = endpoint_profile
        if self.endpoint_profile is None:
            from kernel_optional_engine_module import optional_module
            endpoint_extension = optional_module("STATEFRAME_ENDPOINT_PROFILE_MODULE")
            if endpoint_extension is not None:
                try:
                    self.endpoint_profile = endpoint_extension.endpoint_profile()
                except (AttributeError, OSError, ValueError):
                    self.endpoint_profile = None
        # LOCALIZE owns a cached, revision-bound public index.  It is created
        # lazily on the first targetless S2 search so ordinary target-bearing
        # rows retain their existing startup cost and behavior.
        self.localize_index = None
        self.localize_receipts: list[dict[str, object]] = []
        self._last_localize_result: dict[str, object] | None = None
        self._last_causal_frontier: dict[str, object] | None = None
        from kernel_decisive_factor import mode as decisive_factor_mode
        self.stateframe_decisive_factor_mode = decisive_factor_mode()
        self.decisive_factor = None
        from kernel_memory_isolation import mode as memory_isolation_mode
        self.stateframe_memory_isolation_mode = memory_isolation_mode()
        self.memory_isolation = None
        from kernel_challenge_budget import configured_budget as challenge_budget_configured
        self.stateframe_challenge_budget = challenge_budget_configured()
        from kernel_submission_idempotency import mode as submit_idempotent_mode
        self.stateframe_submit_idempotent_mode = submit_idempotent_mode()
        from kernel_guarded_effects import mode as guarded_effects_mode
        self.stateframe_guarded_effects_mode = guarded_effects_mode()
        if self.stateframe_submit_idempotent_mode == "on":
            # Exactly-once submission needs the budget journal as durable state;
            # refuse the half-enabled configuration instead of degrading.
            from kernel_submission_idempotency import validate_configuration
            validate_configuration("on", self.stateframe_challenge_budget)
        if self.stateframe_challenge_budget is not None:
            from kernel_challenge_budget import new_state as challenge_budget_new_state
            self._challenge_budget_state = challenge_budget_new_state(
                self.stateframe_challenge_budget)
            self._challenge_budget_output = output
        from kernel_verdict_identity import mode as verdict_identity_mode
        self.stateframe_verdict_identity_mode = verdict_identity_mode()
        from kernel_project_registries import mode as project_registries_mode
        self.stateframe_project_registries_mode = project_registries_mode()
        # Append request-assignment annotations only when explicitly enabled.
        # Importing the switch parser does not alter the OFF request shape.
        from experiment_protocol import mode as experiment_protocol_mode
        self.stateframe_experiment_protocol_mode = experiment_protocol_mode()
        self.project_registries = None
        from kernel_completion_authority import mode as completion_authority_mode
        self.stateframe_completion_v2_mode = completion_authority_mode()
        from kernel_prepublish_diff_audit import mode as prepublish_diff_audit_mode
        self.stateframe_prepublish_diff_audit_mode = prepublish_diff_audit_mode()
        from kernel_sweep_fixes import mode as sweep_fixes_mode
        self.stateframe_sweep_fixes_mode = sweep_fixes_mode()
        from kernel_frame_clarity import mode as frame_clarity_mode
        self.frame_clarity_mode = frame_clarity_mode()
        from kernel_hypothesis_projection import mode as hypothesis_projection_mode
        self.stateframe_hypothesis_projection_mode = hypothesis_projection_mode()
        from kernel_frame_display_truth import mode as display_truth_mode
        self.stateframe_display_truth_mode = display_truth_mode()
        from kernel_readiness_authority import mode as readiness_authority_mode
        from kernel_green_then_exhaust import mode as green_then_exhaust_mode
        from kernel_repair_blocks_done import mode as repair_blocks_done_mode
        self.stateframe_repair_blocks_done_mode = repair_blocks_done_mode()
        from kernel_done_challenge_once import mode as done_challenge_once_mode
        self.stateframe_done_challenge_once_mode = done_challenge_once_mode()
        from kernel_challenge_schema import mode as challenge_schema_mode
        self.stateframe_challenge_schema_mode = challenge_schema_mode()
        from kernel_first_green_disclosure import mode as first_green_disclosure_mode
        self.stateframe_first_green_disclosure_mode = first_green_disclosure_mode()
        from kernel_live_counterexample_challenge import mode as live_ce_challenge_mode
        self.stateframe_live_ce_challenge_mode = live_ce_challenge_mode()
        from kernel_adversary import mode as adversary_mode
        self.stateframe_adversary_mode = adversary_mode()
        from kernel_stateframe_notice_dedup import mode as notice_dedup_mode
        self.stateframe_notice_dedup_mode = notice_dedup_mode()
        from kernel_partial_observation import mode as partial_observation_mode
        self.stateframe_partial_observation_mode = partial_observation_mode()
        from kernel_vacuity_sentinel import mode as vacuity_sentinel_mode
        self.stateframe_vacuity_sentinel_mode = vacuity_sentinel_mode()
        from kernel_ship_tree_smoke import mode as ship_tree_smoke_mode
        self.stateframe_ship_tree_smoke_mode = ship_tree_smoke_mode()
        # P2/P3 host site facts (literal site inventory, entry-symbol verification,
        # module head + import fact); default on, STATEFRAME_SITE_FACTS=off disables.
        from kernel_request_source_window import site_facts_mode
        self.stateframe_site_facts_mode = site_facts_mode()
        from kernel_owner_first import allocation_enabled, coordinates_enabled
        self.stateframe_owner_first_alloc_mode = "on" if allocation_enabled() else "off"
        self.stateframe_owner_coords_mode = "on" if coordinates_enabled() else "off"
        from kernel_stateframe_unified_thinking import (
            mode as unified_thinking_mode, notice_budget as unified_thinking_budget,
        )
