        if getattr(self, "stateframe_other_end_contract_mode", "off") == "on":
            manifest['stateframe_other_end_contract'] = "on"
        if getattr(self, "stateframe_check_generator_fixes_mode", "off") == "on":
            manifest['stateframe_check_generator_fixes'] = "on"
        manifest['public_proof_id'] = self.public_proof_id
        manifest['complete_frame_reads'] = (self.projector_kind == 'rich'
                                            and AXES[self.modes['render_selection']][2])
        manifest['latest_exchange_public_id'] = (self.latest_exchange_public_id
            if self.latest_exchange_mode != 'off' else 'inactive')
        if self.latest_exchange_mode != 'off' and (
                self.projector_kind != 'rich' or self.view_kind != 'operational'
                or not AXES[self.modes['render_selection']][2]
                or os.environ.get('REACT_TOOLCALL', '1') != '1'
                or not (os.environ.get('REACT_STEP_CONTRACT', '0') == '1' or native_batches)):
            raise ValueError('latest exchange requires enforced rich operational frames and structured dispatch')
        manifest['retained_context'] = retain_context
        manifest['retained_delivery'] = self.retained_delivery
        manifest['retained_read_focus'] = self.retained_read_focus
        manifest['retained_edit_focus'] = self.retained_edit_focus
        manifest['read_working_set_capacity'] = self.read_working_set_capacity
