        self.public_review_multifile = public_multifile_enabled()
        manifest['public_review_multifile'] = self.public_review_multifile
        manifest['public_review_contract_requested'] = os.environ.get(
            'KERNEL_PUBLIC_REVIEW_CONTRACT', 'literal_single')
        manifest['public_review_contract'] = 'inactive'
        if self.modes['public_review'] != Mode.OFF:
            from kernel_step_contract import enabled
            from kernel_public_review import PublicReview
            if self.modes['public_review'] not in {Mode.SHADOW, Mode.BOTH}:
                raise ValueError('public review supports OFF, SHADOW or BOTH; stop deferral requires effect permission')
            if (self.view_kind != 'operational' or self.projector_kind != 'rich'
                    or not AXES[self.modes['render_selection']][2]
                    or not (enabled() or native_batches)
                    or os.environ.get('REACT_TOOLCALL', '1') != '1'
                    or (self.multi_file and not self.public_review_multifile)):
                raise ValueError('public review requires enforced operational frames and structured dispatch')
            self.public_review = PublicReview(self)
            manifest['public_review_contract'] = self.public_review.contract_profile
            policy = self.public_review.deadline_policy
            manifest['public_review_deadline'] = {'enabled': policy is not None}
            if policy is not None:
                manifest['public_review_deadline'].update(
                    call_seconds=policy.call_seconds, return_reserve_seconds=policy.reserve_seconds,
                    probe_seconds=policy.probe_seconds, authority='OPTIONAL_WORK_ADMISSION_ONLY')
            manifest['public_review_limits'] = {'model_calls': 2, 'executions': 2,
                'output_tokens_per_call': self.public_review.max_tokens, 'execution_timeout_s': 15,
                'authority': 'UNVERIFIED_MODEL_PROPOSAL',
                'max_probe_tests': 8 if self.public_review.contract_profile == 'referenced_suite' else 1,
                'max_probe_source_bytes': 8000}
        self.parent = ACTIVE_PARENT.get() or ParentMeter(
            attempts=1, steps=parse_step_limit(os.environ.get(
                "PILOT_PARENT_STEPS", None if step_limit is None else max(1, step_limit))),
            enforce=self.restart_enabled or AXES[self.modes["pilot"]][2])
        manifest["parent_budget"] = {"limits": dict(self.parent.limits), "enforced": self.parent.enforce}
        manifest["attempt_step_limit"] = step_limit
        manifest["stateframe_projector"] = self.projector_kind
