        manifest['source_presentation'] = self.source_presentation
        manifest['working_source_scope'] = self.working_source_scope
        manifest['nit_bound_green'] = self.nit_bound_green
        manifest['progress_guard'] = self.progress_guard
        manifest['action_menu_guard'] = self.action_menu_guard
        from kernel_decision_state import notes_only
        manifest['working_notes_only'] = notes_only()
        from kernel_working_notebook import enabled as working_notes_enabled
        from kernel_working_notebook import mode as working_notes_mode
        working_notes_v44 = 'STATEFRAME_WORKING_NOTES' in os.environ
        self.stateframe_working_notes_mode = (
            working_notes_mode() if working_notes_v44 else 'off')
        manifest['stateframe_working_notes'] = working_notes_v44 and working_notes_enabled()
        manifest['decision_state'] = self.decision_state is not None
        from kernel_frame_series_runtime import configuration, public_identity_mode
        series_enabled, series_control = configuration()
        if series_enabled and (self.projector_kind != 'rich' or self.view_kind != 'operational'
                or not AXES[self.modes['render_selection']][2]
                or os.environ.get('REACT_TOOLCALL', '1') != '1'
                or not (os.environ.get('REACT_STEP_CONTRACT', '0') == '1' or native_batches)):
            raise ValueError('frame series requires enforced rich operational frames and structured dispatch')
        manifest['frame_series_public_id'] = public_identity_mode() if series_enabled else 'inactive'
        manifest['frame_series'] = series_enabled
        manifest['frame_series_control'] = series_control
        from unit_planner import joint_handoffs_enabled
        manifest['unit_plan_joint_handoffs'] = joint_handoffs_enabled()
        if self.bind_quantity_enabled:
            manifest['bind_quantity'] = 'on'
        if self.figure_it_out_enabled:
            manifest['figure_it_out'] = 'on'
            manifest['figure_it_out_receipt_schema'] = 'figure-it-out-receipt/1'
        if self.probe_gate_enabled:
            manifest['probe_gate'] = 'on'
        if self.disposition_enabled:
            manifest['disposition'] = self.disposition_mode
        manifest['dispatch_multi_file'] = self.multi_file
