                for event in records():
                    if event.get("kind") == "host_obligation_check":
                        raw_receipt = event.get("receipt")
                        if isinstance(raw_receipt, Mapping):
                            try:
                                receipt = CheckReceipt.from_mapping(raw_receipt)
                            except (TypeError, ValueError):
                                continue
                            self.host_check_receipts.append(receipt)
                            self.host_check_cache[receipt.instance_key] = receipt
                    elif event.get("kind") == "host_repair_check":
                        raw_receipt = event.get("receipt")
                        if isinstance(raw_receipt, Mapping):
                            try:
                                receipt = CheckReceipt.from_mapping(raw_receipt)
                            except (TypeError, ValueError):
                                continue
                            self.host_repair_check_receipts.append(receipt)
                            self.host_repair_check_cache[receipt.instance_key] = receipt
                    elif event.get("kind") == "host_repair_episode":
                        episode = event.get("episode")
                        if isinstance(episode, Mapping):
                            self.host_repair_episode = copy.deepcopy(dict(episode))
                    elif event.get("kind") in {"repair_packet_unrenderable", "repair_packet_request_audit"}:
                        audit = event.get("audit")
                        if isinstance(audit, Mapping):
                            self.host_repair_packet_audit = copy.deepcopy(dict(audit))
                    elif event.get("kind") == "host_check_bundle_source":
                        source = event.get("source")
                        if isinstance(source, Mapping):
                            self.host_check_bundle_source = copy.deepcopy(dict(source))
                    elif event.get("kind") == "boundary_check_dispute":
                        result = event.get("result")
                        if isinstance(result, Mapping) and result.get("status") == "RETIRED":
                            self.host_retired_check_ids.add(str(result.get("check_id", "")))
                    elif event.get("kind") == "boundary_contract_cell_bound":
                        self._boundary_binding_journal_keys.add((
                            "cell", str(event.get("contract_cell_hash", ""))))
                    elif event.get("kind") == "boundary_check_bound":
                        self._boundary_binding_journal_keys.add((
                            "check", str(event.get("check_id", ""))))
                    elif event.get("kind") == "boundary_field_rejected":
                        self._boundary_binding_journal_keys.add((
                            "field_rejected", str(event.get("field", ""))))
                    elif event.get("kind") == "completion_reducer_decision":
                        decision = event.get("decision")
